//#region src/core/traits.ts
// =============================================================================
// CORE / TRAITS - names, categories, rated stats, trackers, pools, morality
// -----------------------------------------------------------------------------
// Pure mechanics: no imports from the host layer.
// =============================================================================

class StringUtil {
  static normalize(str: string): string {
    return str.toLowerCase().trim().replace(/\s+/g, '-');
  }

  // The BOUNDARY normalizer: every string entering the engine (command tokens,
  // lorebook list items) passes through this once, so "Alice and Bob",
  // "alice and bob" and "ALIcE and BoB" are all the same internal string:
  // "alice-and-bob". Rules, in order:
  //   1. lowercase + trim;
  //   2. spaces immediately after `@` are removed ("@ sire" -> "@sire");
  //   3. spaces around `::` are removed and `::` collapses to `:` - the path
  //      separator you can type with spaces ("blood :: heal" -> "blood:heal");
  //      a single `:` passes through untouched;
  //   4. spaces adjacent to `,` and `+` are removed (list/pool separators -
  //      "a, b" -> "a,b", "str + brawl" -> "str+brawl");
  //   5. any remaining whitespace run becomes a single `-`.
  // Idempotent: normalizing a normalized string is a no-op. Backtick literals
  // are the escape hatch - the parser skips this for them.
  static normalizeInput(str: string): string {
    return str
      .toLowerCase()
      .trim()
      .replace(/@\s+/g, '@')
      .replace(/\s*::\s*/g, ':')
      .replace(/\s*([,+])\s*/g, '$1')
      .replace(/\s+/g, '-');
  }

  // "blood-potency" / "self_control" -> "Blood Potency" / "Self Control"
  static toTitleCase(str: string): string {
    return str
      .replace(/[-_]+/g, ' ')
      .trim()
      .split(/\s+/)
      .filter(w => w.length > 0)
      .map(w => w[0].toUpperCase() + w.slice(1).toLowerCase())
      .join(' ');
  }
}

type CategoryType =
  | "physical" | "social" | "mental"
  | "talent" | "skill" | "knowledge"
  | "background" | "tracker" | "virtue" | "morality" | "vital" | "discipline";
class Category {
  static readonly PHYSICAL = new Category("physical");
  static readonly SOCIAL = new Category("social");
  static readonly MENTAL = new Category("mental");
  static readonly TALENT = new Category("talent");
  static readonly SKILL = new Category("skill");
  static readonly KNOWLEDGE = new Category("knowledge");
  static readonly BACKGROUND = new Category("background");
  static readonly TRACKER = new Category("tracker");
  static readonly VIRTUE = new Category("virtue");
  static readonly MORALITY = new Category("morality");
  static readonly VITAL = new Category("vital");
  static readonly DISCIPLINE = new Category("discipline");

  public readonly Name: string;
  private constructor(name: CategoryType) {
    this.Name = name;
    Object.freeze(this);
  }
}

type PointSourceType = "base" | "freebie" | "experience" | "downtime";
class PointSource {
  static readonly BASE = new PointSource("base");
  static readonly FREEBIE = new PointSource("freebie");
  static readonly EXPERIENCE = new PointSource("experience");
  static readonly DOWNTIME = new PointSource("downtime");

  public readonly Name: string;
  private constructor(name: PointSourceType) {
    this.Name = name;
    Object.freeze(this);
  }
}

// --- STATS, MODIFIERS & TRACKERS ---
class LedgerEntry {
  constructor(
    public readonly Source: PointSource,
    public readonly AmountAdded: number,
    public readonly CostIncurred: number
  ) { Object.freeze(this); }
}

class StatModifier {
  constructor(
    public readonly Amount: number,
    public readonly IsPermanent: boolean,
    public readonly IgnoresCap: boolean,
    public readonly Description: string
  ) { Object.freeze(this); }
}

class Stat {
  protected readonly _name: string;
  protected readonly _category: Category;
  protected readonly _isImmutable: boolean;
  protected _creationCap: number;
  protected _absoluteCap: number;
  protected readonly _ledger: LedgerEntry[] = [];
  protected _modifiers: StatModifier[] = [];

  constructor(name: string, category: Category, baseValue: number, creationCap: number = 5, absoluteCap: number = 5, isImmutable: boolean = false) {
    this._name = StringUtil.normalize(name);
    this._category = category;
    this._creationCap = creationCap;
    this._absoluteCap = absoluteCap;
    this._isImmutable = isImmutable;

    if (baseValue > 0) this._ledger.push(new LedgerEntry(PointSource.BASE, baseValue, 0));
  }

  get Name(): string { return this._name; }
  get Category(): Category { return this._category; }

  // The actual dots bought on the sheet
  get Value(): number { return this._ledger.reduce((sum, entry) => sum + entry.AmountAdded, 0); }

  // The pool used for rolling (Value + Buffs - Debuffs)
  get EffectiveValue(): number {
    let eff = this.Value;
    let bypassesCap = false;

    for (const mod of this._modifiers) {
      eff += mod.Amount;
      if (mod.IgnoresCap) bypassesCap = true;
    }

    if (!bypassesCap && eff > this._absoluteCap) return this._absoluteCap;
    if (eff < 0) return 0;
    return eff;
  }

  get AuditLog(): LedgerEntry[] { return [...this._ledger]; }

  Allocate(source: PointSource, amount: number, cost: number = 0, bypassCaps: boolean = false): void {
    if (this._isImmutable) throw new Error(`Cannot modify immutable stat: ${this._name}`);

    const isCreationPhase = (source === PointSource.BASE || source === PointSource.FREEBIE);
    const activeCap = isCreationPhase ? this._creationCap : this._absoluteCap;

    if (!bypassCaps && this.Value + amount > activeCap) {
      throw new Error(`Stat ${this._name} cannot exceed cap of ${activeCap} via ${source.Name}.`);
    }
    this._ledger.push(new LedgerEntry(source, amount, cost));
  }

  AddModifier(mod: StatModifier) { this._modifiers.push(mod); }
  RemoveModifierByDesc(desc: string) {
    this._modifiers = this._modifiers.filter(m => m.Description !== desc);
  }
}

// Extends Stat to handle temporary spendable points (Willpower, Resolve, ...)
class Tracker extends Stat {
  private _tempValue: number;

  constructor(name: string, category: Category, baseValue: number, creationCap: number = 10, absoluteCap: number = 10) {
    super(name, category, baseValue, creationCap, absoluteCap);
    this._tempValue = baseValue;
  }

  get Temporary(): number { return this._tempValue; }

  // Sync temporary points when permanent rating increases
  override Allocate(source: PointSource, amount: number, cost: number = 0, bypassCaps: boolean = false): void {
    super.Allocate(source, amount, cost, bypassCaps);
    this._tempValue += amount;
  }

  Spend(amount: number) {
    if (amount < 0) throw new Error("Cannot spend a negative amount.");
    if (this._tempValue < amount) throw new Error(`Not enough temporary ${this._name} to spend.`);
    this._tempValue -= amount;
  }

  Regain(amount: number, canExceedPermanent: boolean = false) {
    if (amount < 0) throw new Error("Cannot regain a negative amount.");
    this._tempValue += amount;
    if (!canExceedPermanent && this._tempValue > this.Value) {
      this._tempValue = this.Value;
    }
  }
}

// =============================================================================
// RESOURCE POOLS - Blood, Quintessence, Paradox, ... (free-floating counters)
// =============================================================================
class Pool {
  private _current: number;
  private _max: number;
  private readonly _name: string;
  private readonly _perTurn: number;
  private readonly _log: Array<{ delta: number; reason: string }> = [];

  constructor(name: string, max: number, start?: number, perTurnLimit: number = Infinity) {
    this._name = StringUtil.normalize(name);
    this._max = max;
    this._perTurn = perTurnLimit;
    this._current = Math.max(0, Math.min(start ?? max, max));
  }

  get Name(): string { return this._name; }
  get Current(): number { return this._current; }
  get Max(): number { return this._max; }
  get PerTurnLimit(): number { return this._perTurn; }
  get AuditLog(): Array<{ delta: number; reason: string }> { return [...this._log]; }

  // Resize the pool (e.g. a vampire lowering generation via diablerie).
  SetMax(max: number, keepRatio: boolean = false): void {
    if (max < 0) throw new Error("Pool max cannot be negative.");
    if (keepRatio && this._max > 0) this._current = Math.round((this._current / this._max) * max);
    this._max = max;
    if (this._current > max) this._current = max;
  }

  Spend(amount: number, reason: string = ""): void {
    if (amount < 0) throw new Error("Cannot spend a negative amount.");
    if (amount > this._perTurn) throw new Error(`Cannot spend more than ${this._perTurn} ${this._name} per turn.`);
    if (amount > this._current) throw new Error(`Not enough ${this._name}: have ${this._current}, need ${amount}.`);
    this._current -= amount;
    this._log.push({ delta: -amount, reason });
  }

  Gain(amount: number, reason: string = ""): number {
    if (amount < 0) throw new Error("Cannot gain a negative amount.");
    const before = this._current;
    this._current = Math.min(this._max, this._current + amount);
    const gained = this._current - before;
    this._log.push({ delta: gained, reason });
    return gained;
  }

  Refill(): void { this._current = this._max; }
}

type MoralityPolarity = "descending" | "ascending";

// A morality rating (a Road/Humanity, or Torment). "descending" traits worsen
// toward 0 (Humanity 0 = lost to the Beast); "ascending" traits worsen toward
// the max (Torment 10 = unplayable). Degenerate() always moves toward the bad
// extreme; Improve() toward the good one.
class MoralityTrait {
  private _value: number;
  private readonly _max: number;
  private readonly _min: number;
  private readonly _unplayableAt: number;
  public readonly Polarity: MoralityPolarity;
  private readonly _log: Array<{ delta: number; reason: string; value: number }> = [];

  constructor(
    public readonly RoadName: string,
    value: number,
    opts: { max?: number; min?: number; polarity?: MoralityPolarity; unplayableAt?: number } = {}
  ) {
    this._max = opts.max ?? 10;
    this._min = opts.min ?? 0;
    this.Polarity = opts.polarity ?? "descending";
    this._unplayableAt = opts.unplayableAt ?? (this.Polarity === "descending" ? this._min : this._max);
    this._value = Math.max(this._min, Math.min(value, this._max));
  }

  get Value(): number { return this._value; }
  get Max(): number { return this._max; }
  get Min(): number { return this._min; }
  get Category(): Category { return Category.MORALITY; }
  get AuditLog(): Array<{ delta: number; reason: string; value: number }> { return [...this._log]; }

  // True once the rating has reached its unplayable extreme.
  get IsUnplayable(): boolean {
    return this.Polarity === "descending" ? this._value <= this._unplayableAt : this._value >= this._unplayableAt;
  }

  // Worsen: a sin / failed Virtue roll moves the rating toward its bad extreme.
  Degenerate(amount: number = 1, reason: string = "degeneration"): void {
    this._change((this.Polarity === "descending" ? -1 : 1) * Math.abs(amount), reason);
  }
  // Improve: penance / redemption moves the rating toward its good extreme.
  Improve(amount: number = 1, reason: string = "penance"): void {
    this._change((this.Polarity === "descending" ? 1 : -1) * Math.abs(amount), reason);
  }

  private _change(delta: number, reason: string): void {
    const next = Math.max(this._min, Math.min(this._value + delta, this._max));
    const applied = next - this._value;
    this._value = next;
    this._log.push({ delta: applied, reason, value: this._value });
  }
}
//#endregion src/core/traits.ts

//#region src/core/cardtext.ts
// =============================================================================
// CORE / CARD TEXT - the readable data language of lorebook cards
// -----------------------------------------------------------------------------
// Every card the engine reads or writes (character sheets, config registries,
// merits, saved rolls, success tables) is written in THIS, not JSON. It is a
// small hand-rolled dialect - the artifact ships with zero dependencies, so a
// partial implementation of real YAML would be worse than a complete
// implementation of something smaller.
//
// The whole grammar:
//
//   # a comment                     '#' at line start or after a space
//   key: value                      the key ends at the first ": " (or a
//                                   trailing ":"), so "he said: hi" is fine
//   key:                            a block: whatever is indented below
//     inner: 1
//   key: value                      a value PLUS an annotation block; the
//     note: why                     value itself lands under `value`
//   key: a, b, c                    an inline list (commas)
//   key:                            a block list
//     - a
//     - b
//   mentor: Velia                   a REPEATED key is a list - the one thing
//   mentor: Belial                  JSON could not say at all
//   - op: immune                    a list of blocks: "- " starts an item and
//     target: fear                  the lines under it belong to that item
//
// Scalars type themselves: 3 is a number, yes/no are booleans, `none` is null,
// anything else is text with its case preserved. Quote ("...") to force text -
// the writer quotes for you whenever it would otherwise be misread.
//
// Two small tables (TEXT_KEYS, LIST_KEYS) let a human write the obvious thing:
// a comma inside a `description` is punctuation, and one `role:` is still a
// list of one. FIELD_ALIASES lets cards spell the engine's camelCase fields
// with hyphens ("difficulty-expr"). Everything else is typed by its shape.
//
// Pure: no imports from the host layer.
// =============================================================================

interface CardMap { [key: string]: CardValue }
type CardValue = string | number | boolean | null | CardValue[] | CardMap;

// A node's own value when it also carries an annotation block:
//   sanctum: 8
//     note: the Library of the Unseen
// reads as { value: 8, note: "..." }. The key IS the key, so nothing needs a
// separate `name:` field - that was the question this answers.
const CARD_VALUE_KEY = "value";

// Keys whose value is prose or a single name: a comma in them is punctuation,
// and a numeric-looking value stays text. Compared case-insensitively.
const TEXT_KEYS = new Set([
  "name", "key", "id", "description", "note", "label", "blurb", "until",
  "interval", "topic", "title", "specialty", "param", "pool", "difficultyexpr",
  "reason", "summary", "botch", "failure", "overflowlabel", "paid", "budget",
]);

// Keys the engine always wants as a list, so one item needs no special syntax
// ("roles: quintessence" is a list of one). Compared case-insensitively.
const LIST_KEYS = new Set([
  "roles", "replaces", "tags", "templates", "meritsflaws", "targetmustbe",
  "apply", "passive", "rows", "steps", "startoptions", "members", "scope",
  "tiers", "bindings", "limits",
]);

// A comma-joined TOKEN string the engine splits itself (EffectOp.target):
// kept as text, but the spacing around the commas is squeezed out.
const TOKEN_TEXT_KEYS = new Set(["target"]);

// Wire spelling <-> engine field, for the handful of fields whose names are
// camelCase. Cards write them hyphenated; anything NOT listed passes through
// untouched, because trait names, merit keys and table names are DATA and must
// never be renamed. The camelCase spelling is also accepted on input.
const FIELD_ALIASES: Record<string, string> = {
  "difficulty-expr": "difficultyExpr",
  "auto-successes": "autoSuccesses",
  "uncancelable-successes": "uncancelableSuccesses",
  "difficulty-mod": "difficultyMod",
  "difficulty-cap": "difficultyCap",
  "min-difficulty": "minDifficulty",
  "dice-mod": "diceMod",
  "merits-flaws": "meritsFlaws",
  "pool-starts": "poolStarts",
  "start-min": "startMin",
  "start-max": "startMax",
  "start-options": "startOptions",
  "per-turn-limit": "perTurnLimit",
  "from-generation": "fromGeneration",
  "at-rating": "atRating",
  "per-kind": "perKind",
  "max-from-trait": "maxFromTrait",
  "fill-to-cap": "fillToCap",
  "requires-resource": "requiresResource",
  "requires-trait": "requiresTrait",
  "requires-awakened": "requiresAwakened",
  "scales-with": "scalesWith",
  "at-least": "atLeast",
  "target-must-be": "targetMustBe",
  "max-per-use": "maxPerUse",
  "reduced-by": "reducedBy",
  "per-success": "perSuccess",
  "vs-difficulty": "vsDifficulty",
  "on-botch": "onBotch",
  "display-name": "displayName",
  "n-again": "nAgain",
};
const WIRE_ALIASES: Record<string, string> =
  Object.fromEntries(Object.entries(FIELD_ALIASES).map(([wire, field]) => [field, wire]));

// The key as the engine knows it (hyphenated wire spelling -> camelCase field).
function canonicalKey(key: string): string {
  const k = key.trim();
  return FIELD_ALIASES[k.toLowerCase()] ?? k;
}
// The key as a card spells it (the inverse; unlisted keys are unchanged).
function wireKey(key: string): string {
  return WIRE_ALIASES[key] ?? key;
}

const lookupKey = (key: string | undefined): string => (key ?? "").toLowerCase();
const isTextKey = (key?: string): boolean => TEXT_KEYS.has(lookupKey(key)) || TOKEN_TEXT_KEYS.has(lookupKey(key));
const isListKey = (key?: string): boolean => LIST_KEYS.has(lookupKey(key));

// =============================================================================
// READING
// =============================================================================

// Everything from an unquoted '#' (line start, or after whitespace) onward.
function stripComment(line: string): string {
  let out = "";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === "\\" && i + 1 < line.length) { out += ch + line[i + 1]; i++; continue; }
      if (ch === '"') quoted = false;
      out += ch;
      continue;
    }
    if (ch === '"') { quoted = true; out += ch; continue; }
    if (ch === "#" && (i === 0 || /\s/.test(line[i - 1]))) return out;
    out += ch;
  }
  return out;
}

// Leading whitespace width; a tab counts as two spaces.
function indentOf(line: string): number {
  let n = 0;
  for (const ch of line) {
    if (ch === " ") n++;
    else if (ch === "\t") n += 2;
    else break;
  }
  return n;
}

// "key: rest" -> the pair. The key ends at the FIRST colon followed by a space
// or end of line, so "trait-affinity:melee: 3" keys on the whole instance name
// and "he said: hi" is a value with a colon in it.
function splitKey(text: string): { key: string; inline: string } | undefined {
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== ":") continue;
    const next = text[i + 1];
    if (next === undefined || next === " " || next === "\t") {
      const key = text.slice(0, i).trim();
      return key.length ? { key, inline: text.slice(i + 1).trim() } : undefined;
    }
  }
  return undefined;
}

// Split on a separator at the top level - inside "..." doesn't count.
function splitTopLevel(text: string, sep: string): string[] {
  const parts: string[] = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === "\\" && i + 1 < text.length) { cur += ch + text[i + 1]; i++; continue; }
      if (ch === '"') quoted = false;
      cur += ch;
      continue;
    }
    if (ch === '"') { quoted = true; cur += ch; continue; }
    if (ch === sep) { parts.push(cur); cur = ""; continue; }
    cur += ch;
  }
  parts.push(cur);
  return parts;
}

// A "..." literal: backslash escapes, closing quote ends it, trailing junk ignored.
function unquote(text: string): string {
  let out = "";
  for (let i = 1; i < text.length; i++) {
    const ch = text[i];
    if (ch === "\\") {
      const n = text[i + 1];
      out += n === "n" ? "\n" : n === "t" ? "\t" : n ?? "";
      i++;
      continue;
    }
    if (ch === '"') break;
    out += ch;
  }
  return out;
}

const NUMBER_RE = /^[+-]?\d+$/;
const DECIMAL_RE = /^[+-]?(?:\d+\.\d*|\.\d+)$/;

// One written value -> a typed scalar (or an inline list). The key matters:
// TEXT_KEYS never split and never auto-type.
function readScalar(raw: string, key?: string): CardValue {
  const t = raw.trim();
  if (!t.length) return "";
  if (t.startsWith('"')) return unquote(t);
  if (TOKEN_TEXT_KEYS.has(lookupKey(key))) return t.replace(/\s*,\s*/g, ",");
  if (isTextKey(key)) return t;
  if (NUMBER_RE.test(t)) return parseInt(t, 10);
  if (DECIMAL_RE.test(t)) return parseFloat(t);
  const low = t.toLowerCase();
  if (low === "true" || low === "yes" || low === "on") return true;
  if (low === "false" || low === "no" || low === "off") return false;
  if (low === "none" || low === "null") return null;
  if (t.includes(",")) {
    const parts = splitTopLevel(t, ",").map(p => readScalar(p)).filter(p => p !== "");
    return parts.length === 1 ? parts[0] : parts;
  }
  return t;
}

interface CardNode { key?: string; inline: string; children: CardNode[] }

// Text -> the indentation tree. Never throws: unreadable lines become items.
function readNodes(text: string): CardNode {
  const root: CardNode = { inline: "", children: [] };
  const stack: { indent: number; node: CardNode }[] = [{ indent: -1, node: root }];
  for (const rawLine of text.split(/\r?\n/)) {
    const line = stripComment(rawLine);
    const body = line.trim();
    if (!body.length) continue;
    const indent = indentOf(line);
    while (stack.length > 1 && indent <= stack[stack.length - 1].indent) stack.pop();
    const parent = stack[stack.length - 1].node;
    let node: CardNode;
    if (body === "-" || body.startsWith("- ")) {
      // A list item. "- key: value" opens a block whose first pair is inline.
      const rest = body === "-" ? "" : body.slice(2).trim();
      node = { inline: "", children: [] };
      const pair = rest.startsWith('"') ? undefined : splitKey(rest);
      if (pair) node.children.push({ key: pair.key, inline: pair.inline, children: [] });
      else node.inline = rest;
    } else {
      const pair = body.startsWith('"') ? undefined : splitKey(body);
      node = pair ? { key: pair.key, inline: pair.inline, children: [] } : { inline: body, children: [] };
    }
    parent.children.push(node);
    stack.push({ indent, node });
  }
  return root;
}

// Add a key, turning a REPEATED key into a list (the format's whole reason for
// existing: two Mentors, three passives).
function addKey(map: CardMap, key: string, value: CardValue): void {
  if (!Object.prototype.hasOwnProperty.call(map, key)) { map[key] = value; return; }
  const cur = map[key];
  if (Array.isArray(cur)) cur.push(value);
  else map[key] = [cur, value];
}

function nodeValue(node: CardNode): CardValue {
  if (!node.children.length) return readScalar(node.inline, node.key);
  const keyed = node.children.filter(c => c.key !== undefined);
  const items = node.children.filter(c => c.key === undefined);
  // No keys below: a plain list block. A stray inline value is the first item.
  if (!keyed.length) {
    const list = items.map(nodeValue);
    return node.inline ? [readScalar(node.inline, node.key), ...list] : list;
  }
  // Keys below: a block. The node's OWN value (inline, else the loose items)
  // lands under `value`; the keys are its annotations.
  const map: CardMap = {};
  if (node.inline) map[CARD_VALUE_KEY] = readScalar(node.inline, node.key);
  else if (items.length) map[CARD_VALUE_KEY] = items.map(nodeValue);
  for (const child of keyed) {
    const key = canonicalKey(child.key as string);
    let value = nodeValue({ ...child, key });
    if (isListKey(key) && !Array.isArray(value)) value = value === "" ? [] : [value];
    addKey(map, key, value);
  }
  return map;
}

// Read a card body. Undefined when there is nothing there; a map when the body
// has keys, a list when it is all "- " items. Never throws - a malformed card
// yields whatever could be read, and the player's text is never destroyed.
function parseCardText(text: string | undefined): CardValue | undefined {
  if (!text || !text.trim().length) return undefined;
  const root = readNodes(text);
  if (!root.children.length) return undefined;
  return nodeValue(root);
}

// =============================================================================
// WRITING
// =============================================================================

const BOOLEAN_WORDS = new Set(["true", "yes", "on", "false", "no", "off", "none", "null"]);

function looksTyped(s: string): boolean {
  return NUMBER_RE.test(s) || DECIMAL_RE.test(s) || BOOLEAN_WORDS.has(s.toLowerCase());
}

function needsQuote(s: string, key?: string): boolean {
  if (!s.length) return true;
  if (s !== s.trim()) return true;
  if (/["\n\r\t]/.test(s)) return true;
  if (/(^|\s)#/.test(s)) return true;
  if (s === "-" || s.startsWith("- ")) return true;
  if (isTextKey(key)) return false;      // text keys neither split nor auto-type
  return s.includes(",") || looksTyped(s);
}

function quote(s: string): string {
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\t/g, "\\t")}"`;
}

function writeScalar(value: CardValue, key?: string): string {
  if (value === null) return "none";
  if (typeof value === "boolean") return value ? "yes" : "no";
  if (typeof value === "number") return Number.isFinite(value) ? String(value) : "none";
  const s = TOKEN_TEXT_KEYS.has(lookupKey(key)) ? String(value).split(",").join(", ") : String(value);
  return needsQuote(s, key) ? quote(s) : s;
}

const isScalar = (v: CardValue | undefined): boolean => v !== undefined && (v === null || typeof v !== "object");
const isMap = (v: CardValue | undefined): v is CardMap => !!v && typeof v === "object" && !Array.isArray(v);

const INLINE_LIST_WIDTH = 88;

function writeBlock(value: CardValue, indent: number, out: string[]): void {
  const pad = " ".repeat(indent);
  if (Array.isArray(value)) {
    for (const item of value) {
      if (isScalar(item)) { out.push(`${pad}- ${writeScalar(item)}`); continue; }
      if (isMap(item)) {
        const entries = Object.entries(item);
        const first = entries.find(([, v]) => isScalar(v));
        if (first) {
          out.push(`${pad}- ${wireKey(first[0])}: ${writeScalar(first[1], first[0])}`);
          for (const [k, v] of entries) if (k !== first[0]) writeEntry(k, v, indent + 2, out);
        } else {
          out.push(`${pad}-`);
          writeBlock(item, indent + 2, out);
        }
        continue;
      }
      out.push(`${pad}-`);
      writeBlock(item, indent + 2, out);
    }
    return;
  }
  if (isMap(value)) {
    for (const [k, v] of Object.entries(value)) writeEntry(k, v, indent, out);
    return;
  }
  out.push(`${pad}${writeScalar(value)}`);
}

function writeEntry(rawKey: string, value: CardValue, indent: number, out: string[]): void {
  const pad = " ".repeat(indent);
  const key = wireKey(rawKey);
  if (value === undefined) return;
  if (isScalar(value)) {
    const written = writeScalar(value, rawKey);
    out.push(value === "" ? `${pad}${key}:` : `${pad}${key}: ${written}`);
    return;
  }
  if (Array.isArray(value)) {
    if (!value.length) { out.push(`${pad}${key}:`); return; }
    if (value.every(isScalar)) {
      const inline = value.map(v => writeScalar(v)).join(", ");
      if (pad.length + key.length + 2 + inline.length <= INLINE_LIST_WIDTH) {
        out.push(`${pad}${key}: ${inline}`);
        return;
      }
    }
    // Every element an annotated value -> write it the way a human would: the
    // key REPEATED, once per value ("mentor: 4" twice, each with its own note).
    if (value.every(v => isMap(v) && CARD_VALUE_KEY in v && isScalar(v[CARD_VALUE_KEY]))) {
      for (const item of value) writeEntry(rawKey, item, indent, out);
      return;
    }
    out.push(`${pad}${key}:`);
    writeBlock(value, indent + 2, out);
    return;
  }
  // A block. When it carries the reserved `value` key, that scalar goes back on
  // the key's own line and the rest becomes the annotation block.
  const entries = Object.entries(value as CardMap);
  const own = entries.find(([k]) => k === CARD_VALUE_KEY);
  const rest = entries.filter(([k]) => k !== CARD_VALUE_KEY);
  if (own && isScalar(own[1])) {
    out.push(`${pad}${key}: ${writeScalar(own[1], rawKey)}`);
    for (const [k, v] of rest) writeEntry(k, v, indent + 2, out);
    return;
  }
  if (!entries.length) { out.push(`${pad}${key}:`); return; }
  out.push(`${pad}${key}:`);
  writeBlock(value, indent + 2, out);
}

// A value -> card text. Top-level blocks are separated by a blank line so a
// long sheet reads as sections rather than one wall.
function formatCardText(value: CardValue | undefined): string {
  if (value === undefined) return "";
  const out: string[] = [];
  if (isMap(value)) {
    for (const [k, v] of Object.entries(value)) {
      const before = out.length;
      writeEntry(k, v, 0, out);
      const multiline = out.length - before > 1;
      if (multiline && before > 0 && out[before - 1] !== "") out.splice(before, 0, "");
    }
  } else {
    writeBlock(value, 0, out);
  }
  return out.join("\n");
}

// One-line rendering, for replies and confirmations that can't spare a block.
function inlineCardText(value: CardValue | undefined): string {
  return formatCardText(value).split("\n").map(l => l.trim()).filter(l => l.length > 0).join("; ");
}

// =============================================================================
// COERCIONS - the schema-directed half
// -----------------------------------------------------------------------------
// The reader is deliberately untyped: it reports what was written, and the
// consumer says what it wants. That is what lets a human write `templates: mage`
// for a list, or a comma inside a sentence, without a syntax for either.
// =============================================================================

// The scalar under a node, digging through an annotation block's `value`.
function ownValue(v: CardValue | undefined): CardValue | undefined {
  return isMap(v) && CARD_VALUE_KEY in v ? v[CARD_VALUE_KEY] : v;
}

function asNumber(v: CardValue | undefined): number | undefined {
  const own = ownValue(v);
  if (typeof own === "number") return own;
  if (typeof own === "boolean") return own ? 1 : 0;
  if (typeof own === "string" && own.trim().length && !isNaN(Number(own))) return Number(own);
  return undefined;
}

function asBool(v: CardValue | undefined): boolean | undefined {
  const own = ownValue(v);
  if (typeof own === "boolean") return own;
  if (typeof own === "number") return own !== 0;
  if (typeof own === "string") {
    const low = own.trim().toLowerCase();
    if (low === "true" || low === "yes" || low === "on") return true;
    if (low === "false" || low === "no" || low === "off") return false;
  }
  return undefined;
}

// Text, re-joining a value a comma made into a list ("immune to fear, and to
// mind control" reads back as the sentence it was written as).
function asText(v: CardValue | undefined, sep = ", "): string | undefined {
  const own = ownValue(v);
  if (own === undefined || own === null) return undefined;
  if (Array.isArray(own)) {
    const parts = own.map(p => asText(p, sep)).filter((p): p is string => p !== undefined);
    return parts.length ? parts.join(sep) : undefined;
  }
  if (isMap(own)) return undefined;
  const s = String(own);
  return s.length ? s : undefined;
}

// A list, wrapping a lone value ("one item" needs no syntax).
function asList(v: CardValue | undefined): CardValue[] {
  if (v === undefined || v === null || v === "") return [];
  if (Array.isArray(v)) return v;
  return [v];
}

function asStringList(v: CardValue | undefined): string[] {
  return asList(v).map(x => asText(x)).filter((x): x is string => x !== undefined && x.length > 0);
}

function asMap(v: CardValue | undefined): CardMap {
  return isMap(v) ? v : {};
}


// A list of blocks that carry their own name: written either as a name-keyed
// map (the readable form) or as "- name: x" items.
function asNamedList(v: CardValue | undefined): Array<{ name: string; body: CardMap }> {
  const out: Array<{ name: string; body: CardMap }> = [];
  if (Array.isArray(v)) {
    for (const item of v) {
      const body = asMap(item);
      const name = asText(body["name"]);
      if (name) out.push({ name, body });
    }
    return out;
  }
  for (const [name, raw] of Object.entries(asMap(v))) {
    if (!name.trim().length) continue;
    out.push({ name, body: isMap(raw) ? raw : { [CARD_VALUE_KEY]: raw } });
  }
  return out;
}

// A stable, order-independent digest of a card's DATA (used to tell a card that
// was merely re-created from one that was edited): keys sorted, lists kept in
// order, formatting and comments gone.
function canonicalCardText(value: CardValue | undefined): string {
  const canon = (v: CardValue | undefined): string => {
    if (v === undefined) return "~";
    if (Array.isArray(v)) return `[${v.map(canon).join(",")}]`;
    if (isMap(v)) {
      return `{${Object.keys(v).sort().map(k => `${k}=${canon(v[k])}`).join(",")}}`;
    }
    return v === null ? "none" : String(v).replace(/\s+/g, " ");
  };
  return canon(value);
}
//#endregion src/core/cardtext.ts

//#region src/core/expr.ts
// =============================================================================
// CORE / EXPRESSIONS - the one arithmetic the engine speaks
// -----------------------------------------------------------------------------
// Every number a chronicle can WRITE instead of hard-code goes through here: a
// dice pool ("dexterity+melee"), a difficulty ("stamina + 3"), an effect cap, a
// purse budget, a trait ceiling, and a derived value ("12 - background:generation").
// One language, so there is one thing to learn and one thing to document.
//
// THE HYPHEN RULE. Trait names contain hyphens (self-control, al-ikhlas,
// assamite-sorcery) and arithmetic needs subtraction. They are told apart by
// what FOLLOWS the hyphen, not by spacing alone:
//
//     self-control          one name      (a letter follows the hyphen)
//     courage - 1           subtraction   (a space follows it)
//     12-generation         subtraction   (a number can never absorb a hyphen)
//
// So `a - b` between two NAMES needs the spaces; everywhere else the hyphen
// falls out right on its own. One sentence, and every expression written before
// this module existed still parses to the same number.
//
// A REFERENCE is a colon-separated path - `courage`, `background:generation`,
// `budget:freebie`. The scope decides what a path means; this module only
// spells them. An unanswered path is worth 0 AND is reported in `unknown`,
// which is the whole point: a typo used to silently read as zero.
//
// Nothing throws. A malformed expression comes back as value 0 with `error`
// set, because a bad card must never take the story down with it.
//
// Pure: no imports, no host access.
// =============================================================================

// One addend of an expression, for the reports that show their work.
interface ExprTerm {
  label: string;                          // the term as written
  value: number;                          // its SIGNED contribution to the total
  kind: "literal" | "ref" | "compound";
  // Subtracted rather than added. A separate flag because a term worth ZERO is
  // still subtracted, and -0 cannot say so.
  negated?: boolean;
  from?: string;                          // where a reference's value came from
  unknown?: boolean;                      // nothing answered this reference
}

interface ExprResult {
  value: number;
  terms: ExprTerm[];                      // the top-level addends, in order
  unknown: string[];                      // every path nothing answered
  error?: string;                         // set when the text could not be read
}

// What a path is worth, and (optionally) where that came from. `undefined` -
// not "0" - is how a scope says it does not know the name.
interface ExprScope {
  lookup(path: string[]): { value: number; from?: string } | undefined;
  // Domain functions beyond the built-ins; `undefined` = no such function.
  call?(name: string, args: number[]): number | undefined;
}

// A scope over a plain map of numbers, for tests and for the simple callers.
function mapScope(values: Record<string, number>): ExprScope {
  return {
    lookup: (path) => {
      const key = path.join(":");
      return key in values ? { value: values[key] } : undefined;
    },
  };
}

// --- TOKENS ------------------------------------------------------------------
type Token =
  | { t: "num"; v: number; start: number; end: number }
  | { t: "name"; v: string; start: number; end: number }
  | { t: "op"; v: string; start: number; end: number };

const isDigit = (c: string): boolean => c >= "0" && c <= "9";
const isLetter = (c: string): boolean => (c >= "a" && c <= "z") || (c >= "A" && c <= "Z");
const isNameStart = (c: string): boolean => isLetter(c) || c === "_" || c === "@";
const isNameChar = (c: string): boolean => isLetter(c) || isDigit(c) || c === "_" || c === "@" || c === "." || c === ":";

function tokenize(src: string): { tokens: Token[]; error?: string } {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (c === " " || c === "\t" || c === "\n" || c === "\r") { i++; continue; }
    const start = i;
    if (isDigit(c)) {
      while (i < src.length && isDigit(src[i])) i++;
      if (src[i] === "." && isDigit(src[i + 1])) { i++; while (i < src.length && isDigit(src[i])) i++; }
      tokens.push({ t: "num", v: parseFloat(src.slice(start, i)), start, end: i });
      continue;
    }
    if (isNameStart(c)) {
      i++;
      // A hyphen belongs to the NAME only when a letter follows it; otherwise it
      // is the subtraction operator. See THE HYPHEN RULE above.
      while (i < src.length && (isNameChar(src[i]) || (src[i] === "-" && isLetter(src[i + 1] ?? "")))) i++;
      // `::` is the path separator everywhere else in the engine and folds to a
      // single `:` internally. The boundary normalizer does that for ordinary
      // arguments - but an expression inside BACKTICKS skips normalization by
      // design, so it has to be done here too or `system::time::now` would be a
      // different name from `system:time:now`.
      tokens.push({ t: "name", v: src.slice(start, i).toLowerCase().replace(/::+/g, ":"), start, end: i });
      continue;
    }
    // Two-character comparisons before one-character ones, or ">=" reads as ">".
    const two = src.slice(i, i + 2);
    if ([">=", "<=", "==", "!="].includes(two)) { tokens.push({ t: "op", v: two, start, end: i += 2 }); continue; }
    if ("+-*/(),><=".includes(c)) { tokens.push({ t: "op", v: c, start, end: ++i }); continue; }
    return { tokens, error: `unexpected "${c}" at position ${i + 1}` };
  }
  return { tokens };
}

// --- BUILT-IN FUNCTIONS ------------------------------------------------------
// Variadic where variadic is what you mean; a scope may add domain functions
// (trait-max, road-virtues, ...) through ExprScope.call.
const BUILTINS: Record<string, (args: number[]) => number> = {
  min: (a) => (a.length ? Math.min(...a) : 0),
  max: (a) => (a.length ? Math.max(...a) : 0),
  sum: (a) => a.reduce((x, y) => x + y, 0),
  abs: (a) => Math.abs(a[0] ?? 0),
  floor: (a) => Math.floor(a[0] ?? 0),
  ceil: (a) => Math.ceil(a[0] ?? 0),
  round: (a) => Math.round(a[0] ?? 0),
};
const BUILTIN_FUNCTIONS: string[] = Object.keys(BUILTINS);

// --- THE PARSER / EVALUATOR --------------------------------------------------
// Recursive descent, evaluating as it goes: there is no tree to keep, because
// nothing re-runs an expression against a different scope.
//
//   condition := disjunction                       (evaluateCondition only)
//   disjunction := conjunction ('or' conjunction)*
//   conjunction := negation ('and' negation)*
//   negation    := 'not' negation | comparison
//   comparison  := expr (('>'|'>='|'<'|'<='|'='|'=='|'!=') expr)?
//   expr    := term (('+' | '-') term)*
//   term    := factor (('*' | '/') factor)*
//   factor  := '-' factor | primary
//   primary := number | name '(' args ')' | name | '(' expr ')'
//
// The comparison layer exists for one reason: an affliction that lasts "until
// the next full moon" or "until his blood runs out" is a CONDITION, not a sum.
// It is reached only through evaluateCondition, so every existing arithmetic
// expression parses exactly as it did - a difficulty or a budget never sees it.
// Truth is 1 and falsehood is 0, so a condition is still a number and still
// composes with the rest of the language.
class Evaluator {
  private pos = 0;
  readonly unknown: string[] = [];
  readonly terms: ExprTerm[] = [];
  error?: string;

  constructor(private readonly src: string, private readonly tokens: Token[], private readonly scope: ExprScope) {}

  private peek(): Token | undefined { return this.tokens[this.pos]; }
  private isOp(v: string): boolean { const t = this.peek(); return !!t && t.t === "op" && t.v === v; }
  private take(): Token | undefined { return this.tokens[this.pos++]; }
  private fail(msg: string): number { this.error ??= msg; return 0; }

  // --- THE CONDITION LAYER (evaluateCondition only) --------------------------
  // `and` / `or` / `not` are NAME tokens, so they are recognised here by value
  // rather than by the tokenizer - which means a trait may still be called
  // "order" or "android" without colliding.
  condition(): number { return this.disjunction(); }

  private isWord(w: string): boolean { const t = this.peek(); return !!t && t.t === "name" && t.v === w; }

  private disjunction(): number {
    let value = this.conjunction();
    while (this.isWord("or")) { this.take(); const rhs = this.conjunction(); value = (value || rhs) ? 1 : 0; }
    return value;
  }

  private conjunction(): number {
    let value = this.negation();
    while (this.isWord("and")) { this.take(); const rhs = this.negation(); value = (value && rhs) ? 1 : 0; }
    return value;
  }

  private negation(): number {
    if (this.isWord("not")) { this.take(); return this.negation() ? 0 : 1; }
    return this.comparison();
  }

  private comparison(): number {
    const left = this.expr(true);
    for (const op of [">=", "<=", "==", "!=", ">", "<", "="] as const) {
      if (!this.isOp(op)) continue;
      this.take();
      const right = this.expr(true);
      switch (op) {
        case ">": return left > right ? 1 : 0;
        case "<": return left < right ? 1 : 0;
        case ">=": return left >= right ? 1 : 0;
        case "<=": return left <= right ? 1 : 0;
        case "!=": return left !== right ? 1 : 0;
        default: return left === right ? 1 : 0;   // "=" and "=="
      }
    }
    return left;
  }

  // The TOP level is where terms are recorded, so `a + b - 3` reports three
  // addends the way the roll report has always shown a pool.
  expr(top = false): number {
    let value = this.termAt(top, 1);
    for (;;) {
      if (this.isOp("+")) { this.take(); value += this.termAt(top, 1); continue; }
      if (this.isOp("-")) { this.take(); value -= this.termAt(top, -1); continue; }
      return value;
    }
  }

  private termAt(top: boolean, sign: number): number {
    const start = this.peek()?.start ?? this.src.length;
    const before = this.terms.length;
    const value = this.term();
    if (!top) return value;
    const label = this.src.slice(start, this.tokens[this.pos - 1]?.end ?? start).trim();
    // A term that recorded exactly one leaf, and IS that leaf, keeps its
    // identity: a bare reference stays a reference. Anything bigger - a
    // product, a parenthesised sum - collapses into a single compound addend.
    const leaf = this.terms.length === before + 1 ? this.terms[before] : undefined;
    this.terms.length = before;
    const negated = sign < 0 ? { negated: true } : {};
    this.terms.push(leaf && leaf.label === label
      ? { ...leaf, value: sign * value, ...negated }
      : { label, value: sign * value, kind: "compound", ...negated });
    return value;
  }

  private term(): number {
    let value = this.factor();
    for (;;) {
      if (this.isOp("*")) { this.take(); value *= this.factor(); continue; }
      if (this.isOp("/")) { this.take(); const d = this.factor(); value = d === 0 ? this.fail("division by zero") : value / d; continue; }
      return value;
    }
  }

  private factor(): number {
    if (this.isOp("-")) { this.take(); return -this.factor(); }
    if (this.isOp("+")) { this.take(); return this.factor(); }
    return this.primary();
  }

  private primary(): number {
    const tok = this.take();
    if (!tok) return this.fail("the expression ends early");
    if (tok.t === "num") {
      this.terms.push({ label: this.src.slice(tok.start, tok.end), value: tok.v, kind: "literal" });
      return tok.v;
    }
    if (tok.t === "op" && tok.v === "(") {
      const value = this.expr();
      if (!this.isOp(")")) return this.fail("a ( is never closed");
      this.take();
      return value;
    }
    if (tok.t !== "name") return this.fail(`"${tok.v}" is not a value`);
    if (this.isOp("(")) return this.callFunction(tok.v);
    const path = tok.v.split(":").filter(p => p.length > 0);
    const hit = this.scope.lookup(path);
    if (!hit) this.unknown.push(tok.v);
    this.terms.push({ label: tok.v, value: hit?.value ?? 0, kind: "ref", from: hit?.from, unknown: !hit });
    return hit?.value ?? 0;
  }

  private callFunction(name: string): number {
    this.take();                                  // the (
    const args: number[] = [];
    const before = this.terms.length;
    if (!this.isOp(")")) {
      for (;;) {
        args.push(this.expr());
        if (this.isOp(",")) { this.take(); continue; }
        break;
      }
    }
    if (!this.isOp(")")) return this.fail(`${name}( is never closed`);
    this.take();
    this.terms.length = before;                   // the arguments are not addends
    const domain = this.scope.call?.(name, args);
    if (domain !== undefined) return domain;
    const builtin = BUILTINS[name];
    if (!builtin) return this.fail(`no function "${name}" (known: ${BUILTIN_FUNCTIONS.join(", ")})`);
    return builtin(args);
  }

  atEnd(): boolean { return this.pos >= this.tokens.length; }
  // What is left over when the parse stopped early - "3 4" and "a b" are not
  // expressions, and saying WHICH text confused it beats "syntax error".
  rest(): string { return this.src.slice(this.peek()?.start ?? this.src.length).trim(); }
}

// Read an expression against a scope. Never throws: a malformed expression is
// worth 0 and says why.
function evaluateExpr(expr: string, scope: ExprScope): ExprResult {
  const src = (expr ?? "").trim();
  if (!src) return { value: 0, terms: [], unknown: [] };
  const { tokens, error } = tokenize(src);
  if (error) return { value: 0, terms: [], unknown: [], error };
  const ev = new Evaluator(src, tokens, scope);
  const value = ev.expr(true);
  if (!ev.error && !ev.atEnd()) ev.error = `nothing joins "${ev.rest()}" to what comes before it`;
  return {
    value: ev.error ? 0 : value,
    terms: ev.error ? [] : ev.terms,
    unknown: ev.error ? [] : ev.unknown,
    ...(ev.error ? { error: ev.error } : {}),
  };
}

// A CONDITION: the same language with comparisons and and/or/not on top,
// answering true or false. This is what "until X" is written in - an affliction
// that lasts "until the next full moon" (`full-moons >= 1`) or "until his blood
// runs out" (`blood <= 0`) or both (`full-moons >= 1 or blood <= 0`).
//
// An empty condition is FALSE, not true: "no condition" must never read as
// "already over", or an affliction with a malformed card would end instantly.
interface ConditionResult extends ExprResult { truth: boolean }
function evaluateCondition(expr: string, scope: ExprScope): ConditionResult {
  const src = (expr ?? "").trim();
  if (!src) return { value: 0, terms: [], unknown: [], truth: false };
  const { tokens, error } = tokenize(src);
  if (error) return { value: 0, terms: [], unknown: [], error, truth: false };
  const ev = new Evaluator(src, tokens, scope);
  const value = ev.condition();
  if (!ev.error && !ev.atEnd()) ev.error = `nothing joins "${ev.rest()}" to what comes before it`;
  return {
    value: ev.error ? 0 : value,
    terms: ev.error ? [] : ev.terms,
    unknown: ev.error ? [] : ev.unknown,
    ...(ev.error ? { error: ev.error } : {}),
    // A condition the engine could not read is FALSE and says why, rather than
    // quietly ending something.
    truth: !ev.error && value !== 0,
  };
}

// A number, or an expression that yields one. Every rules field that a
// chronicle might want to write in terms of the character uses this type.
type Numeric = number | string;

// Resolve one. A malformed or empty expression falls back to the DEFAULT rather
// than to zero, so a bad card degrades to the ordinary rule.
function evalNumeric(value: Numeric | undefined, scope: ExprScope, fallback: number): number {
  if (value === undefined) return fallback;
  if (typeof value === "number") return value;
  const out = evaluateExpr(value, scope);
  return out.error ? fallback : out.value;
}

// Every reference an expression makes, without evaluating it - what a cycle
// check and a "where did this number come from" report are built on.
function exprRefs(expr: string): string[] {
  const { tokens, error } = tokenize((expr ?? "").trim());
  if (error) return [];
  const out: string[] = [];
  tokens.forEach((tok, i) => {
    const next = tokens[i + 1];
    const isCall = next && next.t === "op" && next.v === "(";
    if (tok.t === "name" && !isCall && !out.includes(tok.v)) out.push(tok.v);
  });
  return out;
}

// "Strength 4 + Brawl 3 - 1" - the addends with their values, for a report that
// shows its work. Unknown references are marked, never hidden.
function describeTerms(terms: ExprTerm[]): string {
  return terms.map((t, i) => {
    // The sign is the term's own contribution; a label that already carries a
    // unary sign ("-3") must not print it twice.
    const bare = t.label.replace(/^[-+]\s*/, "");
    const body = t.kind === "literal"
      ? `${Math.abs(t.value)}`
      : `${bare} ${Math.abs(t.value)}${t.unknown ? " (unknown)" : t.from ? ` (${t.from})` : ""}`;
    const minus = t.negated || t.value < 0;
    if (i === 0) return minus ? `-${body}` : body;
    return `${minus ? "-" : "+"} ${body}`;
  }).join(" ");
}
//#endregion src/core/expr.ts

//#region src/core/dice.ts
// =============================================================================
// DICE - auditable Storyteller (World of Darkness) dice roller
// =============================================================================

// Random integer in [min, max]. Uses Math.random by default; an injectable Rng
// (returning a float in [0,1)) keeps rolls deterministic under test.
type Rng = () => number;
const __defaultRng: Rng = () => Math.random();
function Random(min: number, max: number, rng: Rng = __defaultRng): number {
  if (max < min) { const t = min; min = max; max = t; }
  return min + Math.floor(rng() * (max - min + 1));
}

interface RollTrait { name: string; value: number; }
interface RollOptions {
  difficulty?: number;        // default 6
  nAgain?: number;            // default 10 (10-again). 11 disables, 9 explodes 9s & 10s.
  automaticSuccesses?: number; // free successes (e.g. Potence, a spent Willpower)
  uncancelableSuccesses?: number; // successes rolled 1s can NEVER cancel (fused Willpower)
  rng?: Rng;
  label?: string;             // header label when rolling a raw pool
}
interface RollDie {
  face: number;
  symbol: string;        // bomb / explode / hit / miss
  isSuccess: boolean;
  isOne: boolean;
  explodes: boolean;
  fromExplosion: boolean;
}
type RollOutcome = "botch" | "failure" | "success";
interface RollResult {
  traits: RollTrait[];
  pool: number;
  difficulty: number;
  nAgain: number;
  dice: RollDie[];
  successes: number;          // dice meeting difficulty (incl. explosions)
  automaticSuccesses: number; // free successes added to the tally
  uncancelableSuccesses: number; // successes immune to cancellation by 1s
  ones: number;               // dice showing a 1 (incl. explosions)
  net: number;                // successes + automaticSuccesses - ones (+ uncancelable on top)
  isBotch: boolean;
  outcome: RollOutcome;
  message: string;
}

const DIE_BOMB = "\u{1F4A3}";    // bomb -> a rolled 1
const DIE_EXPLODE = "\u{1F4A5}"; // collision -> a die that explodes (n-again)
const DIE_HIT = "✅";        // check -> a success
const DIE_MISS = "❌";       // cross -> a failure
const MAX_DICE = 200;            // safety valve against pathological explosion chains

class Dice {
  // Accepts either a raw pool size or a list of named traits (one or two are
  // typical, but any number is summed). Returns a fully auditable result.
  static roll(input: number | RollTrait[], options: RollOptions = {}): RollResult {
    const difficulty = options.difficulty ?? 6;
    const nAgain = Math.max(2, options.nAgain ?? 10); // never explode on faces < 2
    const automaticSuccesses = Math.max(0, options.automaticSuccesses ?? 0);
    const uncancelableSuccesses = Math.max(0, options.uncancelableSuccesses ?? 0);
    const rng = options.rng ?? __defaultRng;

    const traits: RollTrait[] = typeof input === "number"
      ? [{ name: options.label ?? "Pool", value: input }]
      : input;
    const pool = Math.max(0, traits.reduce((s, t) => s + Math.max(0, t.value), 0));

    const dice: RollDie[] = [];
    let pending = pool;   // remaining dice from the initial pool
    let extra = 0;        // dice queued by explosions
    let rolled = 0;

    const rollOne = (fromExplosion: boolean): void => {
      const face = Random(1, 10, rng);
      const isOne = face === 1;
      const isSuccess = face >= difficulty;
      const explodes = face >= nAgain;
      let symbol = DIE_MISS;
      if (isOne) symbol = DIE_BOMB;
      else if (explodes) symbol = DIE_EXPLODE;
      else if (isSuccess) symbol = DIE_HIT;
      dice.push({ face, symbol, isSuccess, isOne, explodes, fromExplosion });
      if (explodes) extra++;
    };

    while ((pending > 0 || extra > 0) && rolled < MAX_DICE) {
      if (pending > 0) { pending--; rollOne(false); }
      else { extra--; rollOne(true); }
      rolled++;
    }

    const successes = dice.filter(d => d.isSuccess).length;
    const ones = dice.filter(d => d.isOne).length;
    // Uncancelable successes sit OUTSIDE the 1s-cancellation: ones eat the
    // ordinary tally (never below 0) and the uncancelable ones land on top, so
    // the roll always nets at least that many. With none, net keeps its exact
    // historical form (it may go negative).
    const cancelable = successes + automaticSuccesses - ones;
    const net = uncancelableSuccesses > 0 ? Math.max(0, cancelable) + uncancelableSuccesses : cancelable;

    // A botch is judged on the INITIAL roll only: zero successes and >= 1 one.
    // (A cancelled success is a failure, not a botch; a free success also averts it.)
    const initial = dice.filter(d => !d.fromExplosion);
    const initialSuccesses = initial.filter(d => d.isSuccess).length;
    const initialOnes = initial.filter(d => d.isOne).length;
    const isBotch = initialSuccesses === 0 && automaticSuccesses === 0 && uncancelableSuccesses === 0 && initialOnes >= 1;

    const outcome: RollOutcome = isBotch ? "botch" : (net > 0 ? "success" : "failure");

    const autoText = automaticSuccesses > 0 ? ` +${automaticSuccesses} auto` : "";
    const sureText = uncancelableSuccesses > 0 ? ` +${uncancelableSuccesses} sure` : "";
    const header = traits.map(t => `${StringUtil.toTitleCase(t.name)} (${t.value})`).join(" + ") + autoText + sureText;
    const faces = dice.map(d => `${d.symbol}${d.face}`).join(" ");
    let resultLine: string;
    if (isBotch) resultLine = `${DIE_BOMB} BOTCH!`;
    else if (net > 0) resultLine = `${DIE_HIT} ${net} success${net === 1 ? "" : "es"}`;
    else resultLine = `${DIE_MISS} Failure`;
    const message = `${header} vs diff ${difficulty} [${faces}] -> ${resultLine}`;

    return { traits, pool, difficulty, nAgain, dice, successes, automaticSuccesses, uncancelableSuccesses, ones, net, isBotch, outcome, message };
  }
}
//#endregion src/core/dice.ts

//#region src/core/damage.ts
// =============================================================================
// DAMAGE - severity, kind, intensity, source, and self-describing packets
// -----------------------------------------------------------------------------
// A hit is a DamagePacket. Four *independent* facts describe it:
//
//   * Severity  - bashing / lethal / aggravated: how hard it is to soak & heal.
//   * Intensity - the plain *number* of health levels the hit threatens.
//   * Kind(s)   - open-ended descriptors, in the spirit of D&D's energy/damage
//                 types: "piercing", "slashing", "silver", "fire", "sunlight"...
//                 A packet may carry several (a silver bullet is piercing+silver).
//   * Source    - where it came from ("gunshot", "claw", "fangs", "fall"); kept
//                 for flavour and future rules that key off the attack itself.
//
// Crucially, SEVERITY IS NOT INTRINSIC TO THE ATTACK. One gunshot (piercing,
// lethal) is lethal to a mortal, only *bashing* to a vampire (no organs to
// destroy, no blood to lose) and shrugged off entirely by a werewolf - unless
// the round is *silver*, which no amount of regeneration will soak. The target,
// not the weapon, has the final say: every character runs an incoming packet
// through its own DamageReactions - rewriting or ignoring parts of it - *before*
// it soaks and marks its health track.
// =============================================================================

// --- SEVERITY (the bashing / lethal / aggravated axis) ---
type SeverityName = "harmless" | "bashing" | "lethal" | "aggravated" | "fatal";
class Severity {
  static readonly HARMLESS = new Severity("harmless", 0)
  static readonly BASHING = new Severity("bashing", 1);
  static readonly LETHAL = new Severity("lethal", 2);
  static readonly AGGRAVATED = new Severity("aggravated", 3);
  static readonly FATAL = new Severity("fatal", 4);
  
  // Rank orders the three so the health track's wrap-around upgrade rule works
  // and reactions can ask for "at least this bad".
  private constructor(public readonly Name: SeverityName, public readonly Rank: number) { Object.freeze(this); }

  static fromName(name: SeverityName): Severity {
    switch (name) {
      case "bashing": return Severity.BASHING;
      case "lethal": return Severity.LETHAL;
      case "aggravated": return Severity.AGGRAVATED;
      case "harmless": return Severity.HARMLESS;
      case "fatal": return Severity.FATAL;
      default: throw new Error(`Unknown severity: ${name}`);
    }
  }
  static coerce(s: Severity | SeverityName): Severity {
    return typeof s === "string" ? Severity.fromName(s) : s;
  }

  // Ascending order; index === Rank.
  static readonly ORDER: readonly Severity[] = [
    Severity.HARMLESS, Severity.BASHING, Severity.LETHAL, Severity.AGGRAVATED, Severity.FATAL,
  ];
  // The singleton at a rank, clamped to [HARMLESS, FATAL].
  static atRank(rank: number): Severity {
    return Severity.ORDER[Math.max(0, Math.min(Severity.ORDER.length - 1, Math.round(rank)))];
  }

  IsAtLeast(other: Severity): boolean { return this.Rank >= other.Rank; }
  // The worse (higher-ranked) of two severities.
  Max(other: Severity): Severity { return this.Rank >= other.Rank ? this : other; }
  // Assume the value of the neighbouring singleton, clamped.
  Promote(steps: number = 1): Severity { return Severity.atRank(this.Rank + steps); }
  Demote(steps: number = 1): Severity { return Severity.atRank(this.Rank - steps); }
}

// --- KIND & SOURCE (open descriptor sets; any normalized string is valid) ---
type DamageKind = string;
type DamageSource = string;

// Common descriptors, surfaced as constants purely for discoverability and to
// dodge typos. The type is still `string`, so homebrew kinds need no ceremony.
const Kind = {
  BLUDGEONING: "bludgeoning", PIERCING: "piercing", SLASHING: "slashing",
  SILVER: "silver", COLD_IRON: "cold-iron", FIRE: "fire", SUNLIGHT: "sunlight",
  COLD: "cold", ELECTRICITY: "electricity", POISON: "poison", ACID: "acid",
} as const;
const Source = {
  GUNSHOT: "gunshot", BLADE: "blade", FIST: "fist", CLAW: "claw", FANGS: "fangs",
  FALL: "fall", FIRE: "fire", SUNLIGHT: "sunlight",
} as const;

interface DamagePacketInit {
  intensity: number;
  severity: Severity | SeverityName;
  kinds?: Iterable<DamageKind>;
  source?: DamageSource | null;
  // Whether this packet may be soaked at all. Reactions can force `false`
  // (e.g. silver against a werewolf) to punch straight through a soak that
  // would otherwise apply.
  soakable?: boolean;
}

// An immutable description of one incoming hit. Every mutator returns a *copy*,
// so a reaction pipeline can rewrite a packet without disturbing the original.
class DamagePacket {
  public readonly Intensity: number;
  public readonly Severity: Severity;
  public readonly Kinds: ReadonlySet<DamageKind>;
  public readonly Source: DamageSource | null;
  public readonly Soakable: boolean;

  constructor(init: DamagePacketInit) {
    this.Intensity = Math.max(0, Math.floor(init.intensity));
    this.Severity = Severity.coerce(init.severity);
    const kinds = new Set<DamageKind>();
    for (const k of init.kinds ?? []) {
      const n = StringUtil.normalize(k);
      if (n) kinds.add(n);
    }
    this.Kinds = kinds;
    this.Source = init.source ? StringUtil.normalize(init.source) : null;
    this.Soakable = init.soakable ?? true;
    Object.freeze(this);
  }

  static of(init: DamagePacketInit): DamagePacket { return new DamagePacket(init); }

  HasKind(kind: DamageKind): boolean { return this.Kinds.has(StringUtil.normalize(kind)); }
  HasAnyKind(...kinds: DamageKind[]): boolean { return kinds.some(k => this.HasKind(k)); }

  private _init(): DamagePacketInit {
    return {
      intensity: this.Intensity, severity: this.Severity,
      kinds: this.Kinds, source: this.Source, soakable: this.Soakable,
    };
  }
  With(patch: Partial<DamagePacketInit>): DamagePacket { return new DamagePacket({ ...this._init(), ...patch }); }
  WithSeverity(sev: Severity | SeverityName): DamagePacket { return this.With({ severity: sev }); }
  WithIntensity(n: number): DamagePacket { return this.With({ intensity: n }); }
  AddKind(kind: DamageKind): DamagePacket { return this.With({ kinds: [...this.Kinds, kind] }); }
  RemoveKind(kind: DamageKind): DamagePacket {
    const n = StringUtil.normalize(kind);
    return this.With({ kinds: [...this.Kinds].filter(k => k !== n) });
  }
  Unsoakable(): DamagePacket { return this.Soakable ? this.With({ soakable: false }) : this; }

  describe(): string {
    const kinds = this.Kinds.size ? ` {${[...this.Kinds].join(", ")}}` : "";
    const src = this.Source ? ` from ${this.Source}` : "";
    const soak = this.Soakable ? "" : " (unsoakable)";
    return `${this.Intensity} ${this.Severity.Name}${kinds}${src}${soak}`;
  }
}

// --- DAMAGE REACTIONS - a target's veto/rewrite of an incoming packet ---
// Folded left-to-right over the packet before soak; return the packet unchanged
// to pass. Ordering matters: put severity/kind rewrites before mitigation.
// The reaction's view of its owner: just enough to read traits (Fortitude,
// Stamina, ...) without depending on the game layer's LiveCharacter.
interface ReactionTarget { TraitValue(name: string): number; }

interface DamageReaction {
  readonly Label: string;
  Apply(packet: DamagePacket, character?: ReactionTarget): DamagePacket;
}

// Undead (vampires): no organs to rupture, no blood to bleed out. Piercing and
// ballistic wounds that would kill the living do only bashing; fire and sunlight
// are the classic aggravated exceptions and are never talked down.
class UndeadPhysiology implements DamageReaction {
  readonly Label = "Undead physiology";
  Apply(packet: DamagePacket): DamagePacket {
    if (packet.HasAnyKind(Kind.FIRE, Kind.SUNLIGHT)) {
      return packet.WithSeverity(packet.Severity.Max(Severity.AGGRAVATED));
    }
    const piercing = packet.HasAnyKind(Kind.PIERCING) || packet.Source === Source.GUNSHOT;
    if (piercing && packet.Severity === Severity.LETHAL) {
      return packet.WithSeverity(Severity.BASHING);
    }
    return packet;
  }
}

// Regenerators (werewolves & kin): silver (and fire) slip past the healing
// factor - that damage is aggravated and cannot be soaked away. Everything else
// is left for their all-round Stamina soak to simply absorb.
class SilverVulnerability implements DamageReaction {
  readonly Label = "Silver/fire vulnerability";
  constructor(private readonly kinds: DamageKind[] = [Kind.SILVER, Kind.FIRE]) {}
  Apply(packet: DamagePacket): DamagePacket {
    if (packet.HasAnyKind(...this.kinds)) {
      return packet.WithSeverity(packet.Severity.Max(Severity.AGGRAVATED)).Unsoakable();
    }
    return packet;
  }
}

// Worn protection: flat damage reduction against the kinds (or source) it
// actually stops - a ballistic vest turns a lethal gunshot survivable. A
// deliberate simplification of the tabletop "extra soak dice", chosen so that
// `intensity` alone tells the story of how much got through.
class ArmorReaction implements DamageReaction {
  readonly Label: string;
  private readonly _covers: Set<DamageKind>;
  constructor(name: string, private readonly rating: number, covers: DamageKind[]) {
    this.Label = `Armor (${name})`;
    this._covers = new Set(covers.map(k => StringUtil.normalize(k)));
  }
  Apply(packet: DamagePacket): DamagePacket {
    if (this.rating <= 0) return packet;
    const stops = [...packet.Kinds].some(k => this._covers.has(k))
      || (packet.Source !== null && this._covers.has(packet.Source));
    return stops ? packet.WithIntensity(Math.max(0, packet.Intensity - this.rating)) : packet;
  }
}

// =============================================================================
// HEALTH - damage tracks & wound penalties
// =============================================================================

interface HealthLevelDef { name: string; penalty: number; }

// Standard 7-level Storyteller health track.
const STANDARD_HEALTH_LEVELS: HealthLevelDef[] = [
  { name: "Bruised", penalty: 0 },
  { name: "Hurt", penalty: -1 },
  { name: "Injured", penalty: -1 },
  { name: "Wounded", penalty: -2 },
  { name: "Mauled", penalty: -2 },
  { name: "Crippled", penalty: -5 },
  { name: "Incapacitated", penalty: -5 },
];

// How a square may be healed.
type HealPolicy = "normal" | "never" | "special";

// A single health box. `penalty` is the wound penalty it imposes when it is the
// deepest damaged box. Everything else is optional, so a plain
// `{ name, penalty }` (a HealthLevelDef) is a valid square.
interface HealthSquareDef {
  penalty: number;
  name?: string;
  state?: string;      // key linking this box to a HealthStateDef
  heal?: HealPolicy;    // default "normal"
  healCost?: number;    // healing points to clear this box (default 1)
}

// A named health state wired to one or more boxes; its state depends on how many of its
// linked boxes are currently damaged.
interface HealthStateDef {
  key: string;
  name?: string;
  // Given how many linked boxes are damaged (and how many exist), return the
  // current state label, or null for "inactive". Default: active if any hurt.
  state?: (damaged: number, total: number) => string | null;
}

interface HealthTrackConfig {
  squares: HealthSquareDef[];
  states?: HealthStateDef[];
}

interface HealthStateSlot { key: string; name: string; state: string; damaged: number; total: number; }

interface HealthSummary {
  bashing: number; lethal: number; aggravated: number;
  filled: number; capacity: number; overkill: number;
  penalty: number; level: string;
  isIncapacitated: boolean; isDead: boolean;
  states: HealthStateSlot[];
}

// Damage is stored PER BOX, so boxes can carry named states, heal costs, or be
// unhealable. Simple use (ApplyDamage / Heal / Penalty / Level / counts) needs
// none of that and behaves exactly like a plain Storyteller track.
class HealthTrack {
  private readonly _defs: HealthSquareDef[];
  private readonly _damage: (Severity | null)[];
  private readonly _states: HealthStateDef[];
  private _overkill = 0; // damage that spills past a fully-aggravated track
  private readonly _log: Array<{ severity: SeverityName; intensity: number }> = [];

  constructor(config: HealthSquareDef[] | HealthTrackConfig = STANDARD_HEALTH_LEVELS) {
    const cfg: HealthTrackConfig = Array.isArray(config) ? { squares: config } : config;
    if (cfg.squares.length === 0) throw new Error("Health track needs at least one square.");
    this._defs = cfg.squares.map(s => ({ heal: "normal", healCost: 1, ...s }));
    this._damage = this._defs.map(() => null);
    this._states = (cfg.states ?? []).map(c => ({ ...c }));
  }

  get Capacity(): number { return this._defs.length; }
  get Overkill(): number { return this._overkill; }
  get Filled(): number { return this._damage.reduce((n, d) => n + (d ? 1 : 0), 0); }
  get Bashing(): number { return this._count(Severity.BASHING); }
  get Lethal(): number { return this._count(Severity.LETHAL); }
  get Aggravated(): number { return this._count(Severity.AGGRAVATED); }
  get Fatal(): number { return this._count(Severity.FATAL); }
  CountBySeverity(sev: Severity | SeverityName): number { return this._count(Severity.coerce(sev)); }
  private _count(sev: Severity): number { return this._damage.reduce((n, d) => n + (d === sev ? 1 : 0), 0); }

  // Index of the deepest (highest-index) damaged box, or -1 if unhurt.
  private _deepest(): number {
    for (let i = this._damage.length - 1; i >= 0; i--) if (this._damage[i]) return i;
    return -1;
  }

  // Wound penalty = penalty of the deepest damaged box.
  get Penalty(): number { const i = this._deepest(); return i < 0 ? 0 : this._defs[i].penalty; }
  get Level(): string { const i = this._deepest(); return i < 0 ? "Healthy" : (this._defs[i].name ?? `Level ${i + 1}`); }
  get IsIncapacitated(): boolean { return this.Filled >= this.Capacity; }
  get IsDead(): boolean {
    return this._overkill > 0 || this.Aggravated >= this.Capacity || this._damage.some(d => d === Severity.FATAL);
  }

  ApplyDamage(severity: Severity | SeverityName, intensity: number): void {
    const sev = Severity.coerce(severity);
    if (intensity < 0) throw new Error("Damage intensity cannot be negative.");
    if (intensity === 0 || sev === Severity.HARMLESS) return; // harmless deals nothing
    this._log.push({ severity: sev.Name, intensity });
    for (let i = 0; i < intensity; i++) this._applyOne(sev);
  }

  // One level of damage: fill the first empty box; on a full track apply the
  // wrap-around rule (a more-severe hit replaces the least-severe wound,
  // otherwise the least-severe wound is upgraded one step).
  private _applyOne(sev: Severity): void {
    const empty = this._damage.indexOf(null);
    if (empty !== -1) { this._damage[empty] = sev; return; }

    // Full: least-severe filled box (deepest index among ties).
    let idx = -1, leastRank = Infinity;
    for (let i = this._damage.length - 1; i >= 0; i--) {
      const r = this._damage[i]!.Rank;
      if (r < leastRank) { leastRank = r; idx = i; }
    }
    const least = this._damage[idx]!;
    if (sev.Rank > least.Rank) this._damage[idx] = sev;                              // more severe replaces it
    else if (least.Rank < Severity.AGGRAVATED.Rank) this._damage[idx] = Severity.atRank(least.Rank + 1); // wrap up a step
    else this._overkill++;                                                           // aggravated+ full -> overkill
  }

  // Heals up to `amount` boxes of `severity`, shallowest (highest index) first.
  // "never" boxes are skipped; "special" ones only with `allowSpecial`. Returns
  // the number of boxes cleared.
  Heal(severity: Severity | SeverityName, amount: number, opts: { allowSpecial?: boolean } = {}): number {
    return this._heal(severity, amount, Infinity, opts.allowSpecial ?? false).healed;
  }

  // Cost-aware heal: each box costs its `healCost` from `healingPoints`; stops
  // when the budget or `amount` runs out. Returns boxes cleared and points spent.
  HealWithPoints(severity: Severity | SeverityName, amount: number, healingPoints: number, opts: { allowSpecial?: boolean } = {}): { healed: number; pointsSpent: number } {
    return this._heal(severity, amount, healingPoints, opts.allowSpecial ?? false);
  }

  private _heal(severity: Severity | SeverityName, amount: number, budget: number, allowSpecial: boolean): { healed: number; pointsSpent: number } {
    const sev = Severity.coerce(severity);
    if (amount < 0) throw new Error("Heal amount cannot be negative.");
    let healed = 0, pointsSpent = 0;
    for (let i = this._damage.length - 1; i >= 0 && healed < amount; i--) {
      if (this._damage[i] !== sev) continue;
      const policy = this._defs[i].heal ?? "normal";
      if (policy === "never") continue;
      if (policy === "special" && !allowSpecial) continue;
      const cost = this._defs[i].healCost ?? 1;
      if (cost > budget) continue;
      this._damage[i] = null;
      budget -= cost; pointsSpent += cost; healed++;
    }
    return { healed, pointsSpent };
  }

  Reset(): void { for (let i = 0; i < this._damage.length; i++) this._damage[i] = null; this._overkill = 0; }

  // Current state of every active named state wired to the track.
  States(): HealthStateSlot[] {
    const out: HealthStateSlot[] = [];
    for (const c of this._states) {
      let damaged = 0, total = 0;
      for (let i = 0; i < this._defs.length; i++) {
        if (this._defs[i].state === c.key) { total++; if (this._damage[i]) damaged++; }
      }
      const state = c.state ? c.state(damaged, total) : (damaged > 0 ? "active" : null);
      if (state != null) out.push({ key: c.key, name: c.name ?? c.key, state, damaged, total });
    }
    return out;
  }

  Summary(): HealthSummary {
    return {
      bashing: this.Bashing, lethal: this.Lethal, aggravated: this.Aggravated,
      filled: this.Filled, capacity: this.Capacity, overkill: this._overkill,
      penalty: this.Penalty, level: this.Level,
      isIncapacitated: this.IsIncapacitated, isDead: this.IsDead,
      states: this.States(),
    };
  }
}

// =============================================================================
// SOAK - per-template rules for resisting damage
// =============================================================================
interface SoakTypeRule { soakable: boolean; pool: string[]; }
interface SoakSpec {
  bashing: SoakTypeRule;
  lethal: SoakTypeRule;
  aggravated: SoakTypeRule;
  difficulty: number;
}
//#endregion src/core/damage.ts

//#region src/core/time.ts
// =============================================================================
// TIME - pure calendar/clock math (no host)
// -----------------------------------------------------------------------------
// The story runs on a real (proleptic Gregorian) clock: historical Dark Ages
// dates work, durations roll over months/years correctly, and the cursor is
// second-granular so combat's future 3-second turns fit. Everything here is
// PURE - epoch SECONDS (UTC) in and out. The surface syntax is "yyyy-mm-dd-hh"
// (hour optional); durations are "s/m/h/d/w/mo/y" tokens ("2w 4h", "1mo").
// Adding a duration is calendar-aware (Jan 31 + 1mo = Feb 28); the span between
// two instants is reported as a natural breakdown, computed from the real
// endpoints so it is never the ambiguous "how many days IS a month" guess.
// =============================================================================

const padNum = (n: number, w = 2): string => String(Math.trunc(Math.abs(n))).padStart(w, "0");

// Days in a 1-based month of a (possibly historical) year - leap-aware, and safe
// for years < 100 (which Date.UTC would otherwise remap to 1900-1999).
function daysInMonth(year: number, month1to12: number): number {
  const d = new Date(0);
  d.setUTCFullYear(year, month1to12, 0);   // month index `month1to12` = the NEXT month; day 0 = its last previous day
  return d.getUTCDate();
}

function secondsOfDay(d: Date): number {
  return d.getUTCHours() * 3600 + d.getUTCMinutes() * 60 + d.getUTCSeconds();
}

// --- Instants: "yyyy-mm-dd[-hh[:mm[:ss]]]" <-> epoch seconds ------------------

// Parse a story date. Accepts yyyy-mm-dd, yyyy-mm-dd-hh, yyyy-mm-dd-hh:mm, and
// yyyy-mm-dd-hh:mm:ss (the hour may also be space-separated). Returns epoch
// SECONDS (UTC) or a citing error.
function parseStoryDate(raw: string | undefined): number | { error: string } {
  const s = (raw ?? "").trim();
  const m = s.match(/^(\d{1,6})-(\d{1,2})-(\d{1,2})(?:[-\s]+(\d{1,2})(?::(\d{1,2}))?(?::(\d{1,2}))?)?$/);
  if (!m) return { error: `Can't read date "${s}" - use yyyy-mm-dd-hh (e.g. 1197-03-15-08).` };
  const [year, month, day, hour, minute, second] = m.slice(1).map(x => (x === undefined ? 0 : parseInt(x, 10)));
  if (month < 1 || month > 12) return { error: `Month must be 1-12 in "${s}".` };
  const dim = daysInMonth(year, month);
  if (day < 1 || day > dim) return { error: `Day must be 1-${dim} for ${year}-${padNum(month)} in "${s}".` };
  if (hour > 23 || minute > 59 || second > 59) return { error: `Time out of range in "${s}" (hh:mm:ss up to 23:59:59).` };
  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day);
  d.setUTCHours(hour, minute, second, 0);
  return Math.floor(d.getTime() / 1000);
}

// Format epoch seconds as "yyyy-mm-dd hh:mm" (with ":ss" only when nonzero).
function formatStoryDate(epochSeconds: number): string {
  const d = new Date(epochSeconds * 1000);
  const base = `${d.getUTCFullYear()}-${padNum(d.getUTCMonth() + 1)}-${padNum(d.getUTCDate())} ${padNum(d.getUTCHours())}:${padNum(d.getUTCMinutes())}`;
  return d.getUTCSeconds() ? `${base}:${padNum(d.getUTCSeconds())}` : base;
}

// --- Days of the week ---------------------------------------------------------

// The week is the one calendar cycle that never broke: the Gregorian reform of
// 1582 dropped ten DATES but not a single weekday (Thursday 4 Oct was followed
// by Friday 15 Oct), so the weekday of a proleptic-Gregorian instant is the real
// weekday, unbroken back past 1197. What is NOT the same is the date itself - a
// scribe in 1197 wrote Julian, which ran six days behind the Gregorian dates
// this engine stores. The DAY NAME here is right; the NUMBER beside it is the
// Gregorian one.
const WEEKDAYS = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"] as const;
type Weekday = typeof WEEKDAYS[number];

// 0 = Sunday .. 6 = Saturday.
function weekdayOf(epochSeconds: number): number {
  return new Date(epochSeconds * 1000).getUTCDay();
}

function weekdayName(epochSeconds: number): Weekday {
  return WEEKDAYS[weekdayOf(epochSeconds)];
}

const titleCase = (s: string): string => s.replace(/(^|[\s-])([a-z])/g, (_m, lead: string, ch: string) => lead + ch.toUpperCase());

// "Friday 1197-03-15 08:00" - the parseable form with the day it fell on.
function formatStoryDay(epochSeconds: number): string {
  return `${titleCase(weekdayName(epochSeconds))} ${formatStoryDate(epochSeconds)}`;
}

// --- Durations: fixed part (seconds) + calendar part (months) ----------------

// Months and years are calendar-relative (variable length) so they are kept
// apart from the fixed units and applied by walking the calendar.
interface Duration { months: number; seconds: number }

const UNIT_SECONDS: Record<string, number> = {
  s: 1, sec: 1, secs: 1, second: 1, seconds: 1,
  m: 60, min: 60, mins: 60, minute: 60, minutes: 60,
  h: 3600, hr: 3600, hrs: 3600, hour: 3600, hours: 3600,
  d: 86400, day: 86400, days: 86400,
  w: 604800, wk: 604800, wks: 604800, week: 604800, weeks: 604800,
};
const UNIT_MONTHS: Record<string, number> = {
  mo: 1, mon: 1, mons: 1, month: 1, months: 1,
  y: 12, yr: 12, yrs: 12, year: 12, years: 12,
};

// Parse "2w 4h", "1mo", "90s", "3 days" (tokens may be space-separated or not;
// negatives rewind). Returns a Duration or a citing error.
function parseDuration(raw: string | undefined): Duration | { error: string } {
  const s = (raw ?? "").trim().toLowerCase();
  if (!s) return { error: `Needs a duration, e.g. "3d", "2w 4h", "1mo", "90s".` };
  let months = 0, seconds = 0, matched = false;
  const re = /(-?\d+)\s*([a-z]+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(s)) !== null) {
    const n = parseInt(m[1], 10);
    const unit = m[2];
    if (unit in UNIT_MONTHS) months += n * UNIT_MONTHS[unit];
    else if (unit in UNIT_SECONDS) seconds += n * UNIT_SECONDS[unit];
    else return { error: `Unknown time unit "${unit}" in "${s}" - use s/m/h/d/w/mo/y.` };
    matched = true;
  }
  if (!matched) return { error: `Can't read duration "${s}" - use e.g. "3d", "2w 4h", "1mo", "90s".` };
  return { months, seconds };
}

// Add a duration to an instant. The month/year part is applied first, clamping
// the day to the target month's length (Jan 31 + 1mo -> Feb 28), then the fixed
// seconds are added.
function addDuration(epochSeconds: number, dur: Duration): number {
  const d = new Date(epochSeconds * 1000);
  if (dur.months) {
    const targetIndex = d.getUTCMonth() + dur.months;
    const targetYear = d.getUTCFullYear() + Math.floor(targetIndex / 12);
    const targetMonth = ((targetIndex % 12) + 12) % 12;   // 0-11
    const day = Math.min(d.getUTCDate(), daysInMonth(targetYear, targetMonth + 1));
    d.setUTCFullYear(targetYear, targetMonth, day);
  }
  return Math.floor(d.getTime() / 1000) + dur.seconds;
}

// --- Spans between two instants ----------------------------------------------

interface CalendarSpan {
  negative: boolean;                 // b is before a
  years: number; months: number; days: number;
  hours: number; minutes: number; seconds: number;
  totalSeconds: number;              // absolute magnitude
}

// The exact span from a to b, as a natural years/months/days/h:m:s breakdown.
// Whole calendar months are counted from the earlier endpoint (backing off if
// they would overshoot); the remainder is a plain fixed-time difference - so the
// answer is unambiguous and reversible with addDuration.
function diffCalendar(aEpoch: number, bEpoch: number): CalendarSpan {
  const negative = bEpoch < aEpoch;
  const lo = negative ? bEpoch : aEpoch;
  const hi = negative ? aEpoch : bEpoch;
  const totalSeconds = hi - lo;
  const loD = new Date(lo * 1000), hiD = new Date(hi * 1000);

  let months = (hiD.getUTCFullYear() - loD.getUTCFullYear()) * 12 + (hiD.getUTCMonth() - loD.getUTCMonth());
  if (loD.getUTCDate() > hiD.getUTCDate() ||
     (loD.getUTCDate() === hiD.getUTCDate() && secondsOfDay(loD) > secondsOfDay(hiD))) {
    months -= 1;   // the final month has not fully elapsed
  }
  if (months < 0) months = 0;

  let rem = hi - addDuration(lo, { months, seconds: 0 });   // leftover seconds, >= 0
  const years = Math.floor(months / 12);
  const remMonths = months % 12;
  const days = Math.floor(rem / 86400); rem -= days * 86400;
  const hours = Math.floor(rem / 3600); rem -= hours * 3600;
  const minutes = Math.floor(rem / 60); rem -= minutes * 60;
  return { negative, years, months: remMonths, days, hours, minutes, seconds: rem, totalSeconds };
}

// A span as prose: "1 year, 2 months, 14 days, 12 hours" (empty units dropped).
function formatCalendarSpan(span: CalendarSpan): string {
  const parts: string[] = [];
  const push = (n: number, unit: string): void => { if (n) parts.push(`${n} ${unit}${n === 1 ? "" : "s"}`); };
  push(span.years, "year"); push(span.months, "month"); push(span.days, "day");
  push(span.hours, "hour"); push(span.minutes, "minute"); push(span.seconds, "second");
  return parts.length ? parts.join(", ") : "no time";
}

// --- Recovery boundaries: days crossed & full moons ---------------------------

// How many UTC midnights lie in (from, to]. Successive small advances accumulate
// correctly (no "lastRecovery" state needed): each crossing is counted exactly
// once, whichever advance stepped over it. 0 when to <= from (rewinds recover
// nothing).
function countDayBoundaries(fromEpoch: number, toEpoch: number): number {
  if (toEpoch <= fromEpoch) return 0;
  return Math.floor(toEpoch / 86400) - Math.floor(fromEpoch / 86400);
}

// Full moons on the MEAN lunar cycle: the synodic month (29.530588853 days)
// anchored to the 2000-01-06 18:14 UTC new moon, offset half a cycle. Real
// phases wobble a few hours around the mean, so a computed instant can be off
// by up to ~half a day - plenty for a story clock, even proleptically in 1197.
const SYNODIC_SECONDS = 29.530588853 * 86400;
const NEW_MOON_REF = 947182440;                          // 2000-01-06 18:14 UTC
const FULL_MOON_REF = NEW_MOON_REF + SYNODIC_SECONDS / 2;

// How many full-moon instants lie in (from, to]. 0 when to <= from.
function countFullMoons(fromEpoch: number, toEpoch: number): number {
  if (toEpoch <= fromEpoch) return 0;
  return Math.floor((toEpoch - FULL_MOON_REF) / SYNODIC_SECONDS)
       - Math.floor((fromEpoch - FULL_MOON_REF) / SYNODIC_SECONDS);
}

// The first full-moon instant strictly after `epoch` (epoch seconds).
function nextFullMoon(epoch: number): number {
  const k = Math.floor((epoch - FULL_MOON_REF) / SYNODIC_SECONDS) + 1;
  return Math.round(FULL_MOON_REF + k * SYNODIC_SECONDS);
}

// The first new-moon instant strictly after `epoch`.
function nextNewMoon(epoch: number): number {
  const k = Math.floor((epoch - NEW_MOON_REF) / SYNODIC_SECONDS) + 1;
  return Math.round(NEW_MOON_REF + k * SYNODIC_SECONDS);
}

// --- The moon as a PHASE, not just an instant --------------------------------

// An INSTANT and a PHASE are different questions and the engine needs both.
// countFullMoons/nextFullMoon answer "when is the moon exactly full", which is
// what a recovery rule counts. Nobody in the story talks that way: they say it
// IS the full moon for the few nights it looks full. So the cycle is cut into
// eight slices, each CENTERED on its defining instant - the full moon phase runs
// from ~1.85 days before the exact full moon to ~1.85 days after. The two
// therefore disagree on purpose: it can be the full moon tonight while the exact
// instant is still a day out, and both statements are true.
const MOON_PHASES = [
  "new", "waxing-crescent", "first-quarter", "waxing-gibbous",
  "full", "waning-gibbous", "last-quarter", "waning-crescent",
] as const;
type MoonPhase = typeof MOON_PHASES[number];

const MOON_GLYPHS: Record<MoonPhase, string> = {
  "new": "🌑", "waxing-crescent": "🌒", "first-quarter": "🌓", "waxing-gibbous": "🌔",
  "full": "🌕", "waning-gibbous": "🌖", "last-quarter": "🌗", "waning-crescent": "🌘",
};
const MOON_LABELS: Record<MoonPhase, string> = {
  "new": "new moon", "waxing-crescent": "waxing crescent", "first-quarter": "first quarter",
  "waxing-gibbous": "waxing gibbous", "full": "full moon", "waning-gibbous": "waning gibbous",
  "last-quarter": "last quarter", "waning-crescent": "waning crescent",
};

const PHASE_SECONDS = SYNODIC_SECONDS / 8;

interface MoonState {
  phase: MoonPhase;
  index: number;            // 0-7, MOON_PHASES order
  next: MoonPhase;
  age: number;              // seconds since the new moon that opened this cycle
  fraction: number;         // 0..1 through the cycle (0 = new, 0.5 = full)
  illumination: number;     // 0..1 of the disc lit
  waxing: boolean;
  into: number;             // seconds since THIS phase began
  toNext: number;           // seconds until the next phase begins
  begins: number;           // epoch seconds this phase began
  ends: number;             // epoch seconds the next phase begins
}

// Where the moon is at `epoch`. Every date this engine handles is a thousand
// years BEFORE the reference, so the slice index is taken with Math.floor
// (which rounds toward -Infinity and so keeps working) rather than a modulo
// that would flip sign.
function moonAt(epoch: number): MoonState {
  const slice = Math.floor((epoch - NEW_MOON_REF + PHASE_SECONDS / 2) / PHASE_SECONDS);
  const begins = NEW_MOON_REF + slice * PHASE_SECONDS - PHASE_SECONDS / 2;
  const index = ((slice % 8) + 8) % 8;
  const age = (((epoch - NEW_MOON_REF) % SYNODIC_SECONDS) + SYNODIC_SECONDS) % SYNODIC_SECONDS;
  const fraction = age / SYNODIC_SECONDS;
  return {
    phase: MOON_PHASES[index],
    index,
    next: MOON_PHASES[(index + 1) % 8],
    age,
    fraction,
    illumination: (1 - Math.cos(2 * Math.PI * fraction)) / 2,
    waxing: fraction < 0.5,
    into: epoch - begins,
    toNext: begins + PHASE_SECONDS - epoch,
    begins: Math.round(begins),
    ends: Math.round(begins + PHASE_SECONDS),
  };
}

// When the named phase next BEGINS, strictly after `epoch`. Note this is the
// start of the window, not the principal instant: nextMoonPhase(e, "full") comes
// ~1.85 days before nextFullMoon(e).
function nextMoonPhase(epoch: number, phase: MoonPhase): number {
  const k = MOON_PHASES.indexOf(phase);
  const base = NEW_MOON_REF + k * PHASE_SECONDS - PHASE_SECONDS / 2;
  const m = Math.floor((epoch - base) / SYNODIC_SECONDS) + 1;
  return Math.round(base + m * SYNODIC_SECONDS);
}

// A rough span for the moon report: hours matter, seconds do not.
function roundToHour(seconds: number): number {
  return Math.max(0, Math.round(seconds / 3600) * 3600);
}

// "🌔 waxing gibbous (71% lit) - 2 days, 3 hours in, 1 day, 15 hours to the
// full moon". Deliberately says all three things the Storyteller asks for:
// which phase, how deep into it, how long until the next.
function formatMoon(m: MoonState): string {
  // Both spans are bounded by one slice (~3.7 days), so measuring them from
  // epoch 0 can never surface a calendar unit - it is a plain fixed breakdown.
  const span = (secs: number): string => formatCalendarSpan(diffCalendar(0, roundToHour(secs)));
  const pct = Math.round(m.illumination * 100);
  return `${MOON_GLYPHS[m.phase]} ${MOON_LABELS[m.phase]} (${pct}% lit) - ${span(m.into)} in, `
       + `${span(m.toNext)} to the ${MOON_LABELS[m.next]}`;
}
//#endregion src/core/time.ts

//#region src/core/bus.ts
// =============================================================================
// THE EVENT BUS - one place a thing that happened is announced
// -----------------------------------------------------------------------------
// PURE. No `api`, no storage, no imports: this file is the dispatch rule and
// nothing else, so it can be reasoned about and tested on its own. The half
// that talks to other scripts (api.v1.messaging) lives in services.ts and is
// built ON this - see PostOffice.
//
// The owner's model, and it is the right one: every script keeps a POST OFFICE.
// You walk to it to send something, or you wait at home and it brings you what
// arrived. Sending something to yourself still gets delivered.
//
// That last part is why `emit` here is DIRECT and SYNCHRONOUS rather than a
// round trip through messaging. It is NOT an efficiency choice:
//
//   * api.v1.messaging.broadcast() explicitly excludes the sender, so a script
//     literally cannot receive its own broadcast; and
//   * every messaging call is a Promise. An event that leaves and comes back
//     arrives on a LATER TICK - so the thing that raised it has already
//     finished. "Let a handler adjust this roll before it is rolled" is
//     impossible across the wire and trivial in a direct call.
//
// So: local dispatch is a function call, the relay is a message, and the
// PUBLISHER cannot tell the difference. That is the simplicity the owner asked
// for, kept without the trap underneath it.
// =============================================================================

// Handlers run in this order. `monitor` is the observe-only slot: it runs last,
// after everything has had its say, and its verdict is IGNORED - use it for
// logging and ledgers, where reacting is right and interfering is not.
const BUS_PRIORITIES = ["first", "early", "normal", "late", "last", "monitor"] as const;
type BusPriority = typeof BUS_PRIORITIES[number];

// THREE PHASES, and they are not the same axis as priority. Priority orders the
// handlers that all want to do the same KIND of thing; a phase says WHICH KIND:
//
//   before  - the veto. Runs first, and cancelling here means the thing does not
//             happen: `on` and `after` are skipped. This is where a rule that
//             forbids something belongs.
//   on      - the thing itself. The default, and where everything written before
//             phases existed already sits.
//   after   - it happened. Cannot un-happen it (a cancel from `before` or `on`
//             means `after` never runs at all), so this is the ledger's slot,
//             the reply note's, the cache invalidation's.
//
// WITHIN a phase, `cancelled` stays what it always was - a flag later handlers
// may honour or ignore. BETWEEN phases it is binding. That is the whole
// difference, and it is why a veto needs its own phase rather than a priority:
// `first` could always be out-voted by someone who simply did not check.
const BUS_PHASES = ["before", "on", "after"] as const;
type BusPhase = typeof BUS_PHASES[number];

// A channel whose name starts with this NEVER leaves the script: the post
// office recognises it and simply hands it back down the hall. Anything else is
// relayed. (The owner's "loco" prefix, spelled the way the rest of the engine
// spells things.)
const LOCAL_PREFIX = "local:";
function isLocalChannel(channel: string): boolean {
  return channel.trim().toLowerCase().startsWith(LOCAL_PREFIX);
}

// THE SYSTEM CHANNELS: events the parts of this engine raise at each other,
// never at the outside world. They are `local:` (so they never reach the wire)
// and they are the ONLY events that CAUSE things - a command publishes one and
// a handler does the work, rather than the command doing the work and
// announcing it afterwards. That inversion is the point: the thing that knows
// WHEN is not the thing that knows HOW.
const SYSTEM = {
  powerTaken: `${LOCAL_PREFIX}power:taken`,
  powerLost: `${LOCAL_PREFIX}power:lost`,
  afflictionRequested: `${LOCAL_PREFIX}affliction:requested`,
  afflictionLiftRequested: `${LOCAL_PREFIX}affliction:lift-requested`,
} as const;

// A channel can be ANYTHING - that was the owner's point, and it is worth
// keeping. "character-healed-aggravated-with-a-resource" is a perfectly good
// channel; so is "rolls". Names are normalized only by case and trimming, so
// two spellings of the same intent cannot drift apart.
function busChannel(name: string): string {
  return name.trim().toLowerCase();
}

// What handlers actually see. `cancelled` is a FLAG, not an interruption: later
// handlers still run and may honour it (`if (event.cancelled) return;`) or
// ignore it entirely. `stopped` is the interruption - nothing further runs, and
// the post office does not relay it onward.
interface BusEvent<T = unknown> {
  channel: string;
  data: T;
  // The script this arrived from, absent when it was raised right here. The
  // difference matters: a handler may want to act only on local events, or only
  // on foreign ones, and it should never have to guess.
  from?: string;
  at: number;              // epoch ms (the relayed ScriptMessage's timestamp)
  cancelled: boolean;
  stopped: boolean;
  // A handler that throws does not take the emit down with it: the failure is
  // recorded here and the rest of the handlers still run. Same law as a bad
  // lorebook card - surfaced, never fatal.
  errors: string[];
  // ASYNC WORK A HANDLER STARTED. `emit` is synchronous on purpose - a verdict
  // has to be readable on the next line - but a handler that must touch storage
  // cannot be. So it pushes its promise here and the PUBLISHER awaits them all
  // before returning. Verdicts stay synchronous; effects may take their time.
  pending: Array<Promise<unknown>>;
}

// What a handler may say on the way out. Returning nothing is the common case.
interface BusVerdict { cancel?: boolean; stop?: boolean }
type BusHandler<T = unknown> = (event: BusEvent<T>) => BusVerdict | void;

// Third argument to `on`. A bare priority still works and still means the `on`
// phase, so nothing written before phases existed has to move.
interface BusSubscribeOptions { phase?: BusPhase; priority?: BusPriority }

interface Subscription {
  id: number; channel: string; phase: BusPhase; priority: BusPriority; handler: BusHandler;
}

class EventBus {
  private _subs: Subscription[] = [];
  private _next = 1;
  // Bumped on every subscribe/unsubscribe. The post office watches it to know
  // when its announced interests have gone stale, which is cheaper and more
  // exact than diffing the channel list on every publish.
  private _version = 0;
  get version(): number { return this._version; }

  // Subscribe. The number back is the handle `off` takes - the same shape
  // api.v1.messaging.onMessage uses, so the two layers read alike.
  on<T = unknown>(
    channel: string,
    handler: BusHandler<T>,
    opts: BusPriority | BusSubscribeOptions = "normal",
  ): number {
    const { phase = "on", priority = "normal" } = typeof opts === "string" ? { priority: opts } : opts;
    const id = this._next++;
    this._subs.push({ id, channel: busChannel(channel), phase, priority, handler: handler as BusHandler });
    this._version++;
    return id;
  }

  off(id: number): boolean {
    const before = this._subs.length;
    this._subs = this._subs.filter(s => s.id !== id);
    if (this._subs.length < before) { this._version++; return true; }
    return false;
  }

  // Every handler on a channel, in the order they will run: by phase, then by
  // priority, then by registration. Exposed because "who is listening to this,
  // and when" is a question worth being able to answer out loud. Pass a phase
  // to ask about just that one.
  listeners(channel: string, phase?: BusPhase): Array<{ id: number; phase: BusPhase; priority: BusPriority }> {
    const key = busChannel(channel);
    return this._subs
      .filter(s => s.channel === key && (phase === undefined || s.phase === phase))
      .sort((a, b) =>
        BUS_PHASES.indexOf(a.phase) - BUS_PHASES.indexOf(b.phase) ||
        BUS_PRIORITIES.indexOf(a.priority) - BUS_PRIORITIES.indexOf(b.priority) ||
        a.id - b.id)
      .map(s => ({ id: s.id, phase: s.phase, priority: s.priority }));
  }

  channels(): string[] { return [...new Set(this._subs.map(s => s.channel))].sort(); }

  // Announce something. SYNCHRONOUS: by the time this returns, every local
  // handler has run and the event carries their verdicts - which is exactly
  // what lets a caller ask "was this cancelled?" and act on the answer.
  //
  // The three phases run in order and a cancel BETWEEN them is binding: veto in
  // `before` and neither `on` nor `after` happens; cancel in `on` and `after` is
  // skipped. Within a phase nothing changes - `cancelled` is still the flag it
  // always was.
  emit<T = unknown>(channel: string, data: T, meta: { from?: string; at?: number } = {}): BusEvent<T> {
    const event: BusEvent<T> = {
      channel: busChannel(channel), data,
      ...(meta.from ? { from: meta.from } : {}),
      at: meta.at ?? Date.now(),
      cancelled: false, stopped: false, errors: [], pending: [],
    };
    for (const phase of BUS_PHASES) {
      // A veto earlier in the chain means the later phases simply do not run.
      if (event.stopped || event.cancelled) break;
      this._runPhase(event, phase);
    }
    return event;
  }

  private _runPhase<T>(event: BusEvent<T>, phase: BusPhase): void {
    for (const { id } of this.listeners(event.channel, phase)) {
      if (event.stopped) break;
      const sub = this._subs.find(s => s.id === id);
      if (!sub) continue;   // a handler that unsubscribed a handler mid-emit
      try {
        const verdict = sub.handler(event as BusEvent);
        // A monitor watches; it does not vote.
        if (sub.priority === "monitor" || !verdict) continue;
        if (verdict.cancel) event.cancelled = true;
        if (verdict.stop) event.stopped = true;
      } catch (err) {
        event.errors.push(`${event.channel} handler #${id}: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  }
}
//#endregion src/core/bus.ts

//#region src/wizard.ts
// =============================================================================
// WIZARD - a medium-agnostic engine for guided, multi-step configuration
// -----------------------------------------------------------------------------
// A wizard definition is a small state machine over PLAIN-JSON state: start()
// yields the first prompt, answer(state, reply) consumes a normalized reply and
// yields the next prompt (or done). Prompts are STRUCTURED (kind, options with
// value+label, default, progress) so any medium can render them: the text
// "prompt -> reply" renderer below is one medium; a future api.v1.ui renderer
// can map the same prompts to windows with buttons and feed replies to the same
// answer(). The engine knows nothing about storage or the host - sessions are
// persisted by the caller (game layer).
// =============================================================================

interface WizardOption { value: string; label: string; description?: string }

interface WizardPrompt {
  step: string;                                   // step id (stable per prompt)
  title: string;
  body: string;
  kind: "choice" | "number" | "text" | "confirm";
  options?: WizardOption[];                       // for kind "choice"
  default?: string;                               // "keep" / empty accepts this
  progress?: { at: number; of: number };
}

type WizardStateData = Record<string, unknown>;

interface WizardResult {
  state?: WizardStateData;   // updated state (present while the wizard runs)
  prompt?: WizardPrompt;     // next prompt (absent when done)
  error?: string;            // reply rejected; re-ask the same prompt
  done?: boolean;
  summary?: string;          // closing message when done
}

interface WizardDefinition {
  id: string;
  title: string;
  start(ctx: unknown): WizardResult | Promise<WizardResult>;
  answer(state: WizardStateData, reply: string): WizardResult | Promise<WizardResult>;
}

// Normalize a raw reply against a prompt: option number/value/label for a
// choice, integer for a number, yes/no for a confirm, verbatim for text.
// "keep" (or an empty reply) accepts the prompt's default when one exists.
// "cancel" is NOT handled here - the session layer owns exiting.
function resolveReply(prompt: WizardPrompt, raw: string): { value: string } | { error: string } {
  const t = raw.trim();
  if ((t === "" || /^keep$/i.test(t)) && prompt.default !== undefined) return { value: prompt.default };
  switch (prompt.kind) {
    case "choice": {
      const opts = prompt.options ?? [];
      const i = parseInt(t, 10);
      if (!Number.isNaN(i) && i >= 1 && i <= opts.length) return { value: opts[i - 1].value };
      const hit = opts.find(o => o.value.toLowerCase() === t.toLowerCase() || o.label.toLowerCase() === t.toLowerCase());
      return hit ? { value: hit.value } : { error: `reply with an option (1-${opts.length})` };
    }
    case "number": {
      const v = parseInt(t, 10);
      return Number.isNaN(v) ? { error: "reply with a number" } : { value: String(v) };
    }
    case "confirm": {
      if (/^(y|yes|true)$/i.test(t)) return { value: "yes" };
      if (/^(n|no|false)$/i.test(t)) return { value: "no" };
      return { error: 'reply "yes" or "no"' };
    }
    default:
      return { value: t };
  }
}

// The text medium: one prompt -> one single-line message (the host forbids
// newlines in inputText anyway).
function renderPromptText(p: WizardPrompt): string {
  const prog = p.progress ? `[${p.progress.at}/${p.progress.of}] ` : "";
  const opts = (p.options ?? []).map((o, i) => `${i + 1}) ${o.label}${o.description ? ` - ${o.description}` : ""}`).join("  ");
  const hint = p.kind === "number" ? "reply with a number"
    : p.kind === "confirm" ? 'reply "yes" or "no"'
    : p.kind === "choice" ? "reply with an option number"
    : "reply with text";
  const keep = p.default !== undefined ? `; "keep" = ${p.default === "" ? "skip" : p.default}` : "";
  return `${prog}${p.title} - ${p.body}${opts ? ` ${opts}.` : ""} (${hint}${keep}; "cancel" exits)`;
}
//#endregion src/wizard.ts

//#region src/rolls.ts
// =============================================================================
// ROLLS - turn a player's roll request into dice, with contextual modifiers
// -----------------------------------------------------------------------------
// Pure: depends only on core (Dice + StringUtil). A RollSpec is the declarative,
// serializable description of a roll (pool expression, difficulty, requirement,
// dice/difficulty modifiers, tags). resolveSpec turns it into concrete numbers
// against a TraitResolver, folding in any tag-driven RollModifiers; executeRoll
// then rolls it via core Dice. Keeping the spec separate and serializable is
// what will let players save and re-run "named rolls" later.
// =============================================================================

// Resolves a trait name to its dice value (0 when the character lacks it).
type TraitResolver = (name: string) => number;

const DEFAULT_DIFFICULTY = 6;

// A declarative, serializable roll. `pool` is an expression ("strength+brawl",
// "7", "3+2", "willpower"); the rest are the Storyteller's knobs.
interface RollSpec {
  pool: string;
  difficulty: number;     // base target number (default 6); ignored if difficultyExpr is set
  difficultyExpr?: string; // difficulty as a pool expression (a trait or calculation,
                          // e.g. "stamina+3"); evaluated against the roller's traits
  difficultyMod: number;  // +/- applied to difficulty (default 0)
  requires: number;       // successes needed to count as a success (default 1)
  diceMod: number;        // +/- dice added to the resolved pool (default 0)
  // Successes granted before a die is thrown. `autoSuccesses` are ordinary ones
  // that a rolled 1 can cancel; `uncancelableSuccesses` are the certain kind
  // (fused Willpower). Both exist on the spend/passive path already - these are
  // the SPEC's own, so a Storyteller can hand them out and a named roll can
  // bake them in ("Potence punch: +2 automatic").
  autoSuccesses?: number;
  uncancelableSuccesses?: number;
  tags: string[];         // contextual mechanic keys (normalized)
  difficultyCap?: number; // ceiling the die target clamps to (default 10); anything
                          // above it becomes +1 required success per point - Mage
                          // spellcasting sets 10 (or the book's 9) here
  // Floor the die target never drops below, however deep the reductions run.
  // Unset = no floor of its own; the chronicle's global floor (if it set one)
  // fills in, and failing that only the engine's hard minimum of 2 applies.
  minDifficulty?: number;
}

// Fill defaults and normalize tags. `requires` is at least 1.
function makeRollSpec(parts: Partial<RollSpec> & { pool: string }): RollSpec {
  const spec: RollSpec = {
    pool: parts.pool,
    difficulty: parts.difficulty ?? DEFAULT_DIFFICULTY,
    difficultyMod: parts.difficultyMod ?? 0,
    requires: Math.max(1, parts.requires ?? 1),
    diceMod: parts.diceMod ?? 0,
    tags: (parts.tags ?? []).map(t => StringUtil.normalize(t)).filter(t => t.length > 0),
  };
  if (parts.autoSuccesses) spec.autoSuccesses = parts.autoSuccesses;
  if (parts.uncancelableSuccesses) spec.uncancelableSuccesses = parts.uncancelableSuccesses;
  if (parts.difficultyExpr && parts.difficultyExpr.trim()) spec.difficultyExpr = parts.difficultyExpr.trim();
  if (parts.difficultyCap !== undefined) spec.difficultyCap = Math.max(2, Math.min(10, parts.difficultyCap));
  if (parts.minDifficulty !== undefined) spec.minDifficulty = Math.max(2, Math.min(10, parts.minDifficulty));
  return spec;
}

// --- POOL EXPRESSION ---
interface PoolPart { token: string; value: number; isLiteral: boolean; }
interface PoolBreakdown { parts: PoolPart[]; total: number; unknown: string[]; error?: string }

// A TraitResolver, seen as the expression language's scope: a pool names
// traits, so a path is just a name (`background:generation` reaches the
// resolver as the whole string, and the character scope splits it there).
function resolverScope(resolve: TraitResolver): ExprScope {
  return { lookup: (path) => ({ value: resolve(path.join(":")) }) };
}

// "strength+brawl" / "3+2" / "7" / "willpower" / "strength + brawl - 1" ->
// summed dice (>= 0), through the one expression language (core/expr.ts). The
// pool source is USUALLY a single token, because a bare `[[roll ...]]` argument
// cannot contain spaces without quoting - but a saved roll or a card may write
// it out in full.
function parsePoolExpression(expr: string, resolve: TraitResolver): PoolBreakdown {
  const out = evaluateExpr(expr, resolverScope(resolve));
  const parts: PoolPart[] = out.terms.map(t => ({ token: t.label, value: t.value, isLiteral: t.kind === "literal" }));
  return {
    parts, total: Math.max(0, out.value), unknown: out.unknown,
    ...(out.error ? { error: out.error } : {}),
  };
}

function prettyPool(expr: string): string {
  return expr.split("+").map(t => t.trim()).filter(t => t.length > 0)
    .map(t => /^-?\d+$/.test(t) ? t : StringUtil.toTitleCase(t)).join(" + ");
}

// --- CONTEXTUAL MODIFIERS (tags) ---
// A modifier keyed by a roll tag: matching tags adjust the difficulty, the dice
// pool, free successes, or the n-again threshold before the roll. This is how
// "rules for things" (merits/flaws, situational modifiers) attach to a roll -
// the roll carries tags, each matching modifier fires. Tags are strings, so
// they ride along in a saved (named) roll unchanged.
interface RollModifier {
  tag: string;             // normalized on registration
  describe: string;
  difficultyMod?: number;
  diceMod?: number;
  autoSuccesses?: number;
  uncancelableSuccesses?: number; // successes 1s can never cancel (fused Willpower)
  nAgain?: number;         // tighten n-again (e.g. 9 for 9-again); never loosens
}

// Starter set; a chronicle can register more. These name the *situation* (the
// ST tags the roll), not the character's owned merits - auto-deriving modifiers
// from a character's Merits/Flaws is a planned follow-up.
const DEFAULT_ROLL_MODIFIERS: RollModifier[] = [
  { tag: "Acute Senses", describe: "Acute Senses: -2 difficulty on the sharpened sense.", difficultyMod: -2 },
  { tag: "off-hand", describe: "Off-hand action: +1 difficulty (cancelled by Ambidextrous).", difficultyMod: 1 },
  { tag: "Ambidextrous", describe: "Ambidextrous: cancels the off-hand penalty.", difficultyMod: -1 },
  { tag: "Willpower", describe: "Spent Willpower: +1 automatic success.", autoSuccesses: 1 },
  { tag: "specialty", describe: "Relevant specialty: 9s count again (9-again).", nAgain: 9 },
  // Identity tags [[cast]] stamps on every spell roll: no effect of their own,
  // but magic-keyed powers/effects gate on them (target:"magic"), and they must
  // not read as typos.
  { tag: "magic", describe: "A spell roll." },
  { tag: "cast", describe: "The casting action." },
  // Where the character IS. These tags carry no modifier of their own - the
  // afflictions that grant them scale off a Background rating instead - but
  // they must not read as typos on every roll made there.
  { tag: "in-sanctum", describe: "Standing in their own sanctum." },
  { tag: "in-umbra", describe: "Walking the spirit world." },
  { tag: "in-library", describe: "Among their books." },
  { tag: "in-rotunda", describe: "In the Hermetic rotunda." },
  { tag: "full-rested", describe: "Eight hours of sleep behind them." },
  { tag: "hermetic", describe: "A matter of Hermetic lore." },
];

class RollModifierRegistry {
  private static _mods: Map<string, RollModifier> =
    new Map(DEFAULT_ROLL_MODIFIERS.map(m => [StringUtil.normalize(m.tag), { ...m, tag: StringUtil.normalize(m.tag) }]));

  static register(mod: RollModifier): void {
    const tag = StringUtil.normalize(mod.tag);
    RollModifierRegistry._mods.set(tag, { ...mod, tag });
  }
  static get(tag: string): RollModifier | undefined { return RollModifierRegistry._mods.get(StringUtil.normalize(tag)); }
  static all(): RollModifier[] { return [...RollModifierRegistry._mods.values()]; }
  static reset(): void {
    RollModifierRegistry._mods = new Map(DEFAULT_ROLL_MODIFIERS.map(m => [StringUtil.normalize(m.tag), { ...m, tag: StringUtil.normalize(m.tag) }]));
  }
}

// --- RESOLUTION & EXECUTION ---
// How to treat a final difficulty above 10. Default charges an extra required
// success per point over 10 (the die target caps at 10); "impossible" fails the
// action outright. Both are Storyteller-authentic; extra-success is the default.
type OverDifficultyPolicy = "extra-success" | "impossible";

interface ResolvedRoll {
  spec: RollSpec;
  breakdown: PoolBreakdown;
  dice: number;               // pool after diceMod (>= 0)
  dieDifficulty: number;      // clamped to [2, cap] - what the dice actually use
  requires: number;           // successes needed (incl. any over-cap surcharge)
  automaticSuccesses: number;
  uncancelableSuccesses: number;
  nAgain: number;
  rawDifficulty: number;      // pre-clamp difficulty (may exceed the cap or dip below 2)
  overflow: number;           // max(0, rawDifficulty - cap)
  impossible: boolean;        // over-cap under the "impossible" policy
  appliedTags: string[];
  unknownTags: string[];
  notes: string[];
}

// `usedTags` are tags something OUTSIDE the modifier registry already acted on -
// an affliction or a passive gated on them. They are not "unknown": reporting
// them as such tells a player their tag did nothing when it did the whole job.
function resolveSpec(spec: RollSpec, resolve: TraitResolver, opts: { overDifficulty?: OverDifficultyPolicy; extra?: Partial<RollModifier>; usedTags?: string[] } = {}): ResolvedRoll {
  const breakdown = parsePoolExpression(spec.pool, resolve);
  // Difficulty may be a plain number or an expression (a trait/calculation)
  // evaluated against the SAME resolver as the pool - e.g. "stamina+3".
  const baseDifficulty = spec.difficultyExpr ? parsePoolExpression(spec.difficultyExpr, resolve).total : spec.difficulty;
  let difficulty = baseDifficulty + spec.difficultyMod;
  let dice = breakdown.total + spec.diceMod;
  let automaticSuccesses = spec.autoSuccesses ?? 0;
  let uncancelableSuccesses = spec.uncancelableSuccesses ?? 0;
  let nAgain = 10;
  const appliedTags: string[] = [];
  const unknownTags: string[] = [];
  for (const tag of spec.tags) {
    const mod = RollModifierRegistry.get(tag);
    if (!mod) {
      if (!(opts.usedTags ?? []).includes(tag)) unknownTags.push(tag);
      continue;
    }
    appliedTags.push(tag);
    difficulty += mod.difficultyMod ?? 0;
    dice += mod.diceMod ?? 0;
    automaticSuccesses += mod.autoSuccesses ?? 0;
    uncancelableSuccesses += mod.uncancelableSuccesses ?? 0;
    if (mod.nAgain !== undefined) nAgain = Math.min(nAgain, mod.nAgain);
  }

  // An ad-hoc modifier (e.g. a spent resource's effect) applied like a matched tag.
  if (opts.extra) {
    difficulty += opts.extra.difficultyMod ?? 0;
    dice += opts.extra.diceMod ?? 0;
    automaticSuccesses += opts.extra.autoSuccesses ?? 0;
    uncancelableSuccesses += opts.extra.uncancelableSuccesses ?? 0;
    if (opts.extra.nAgain !== undefined) nAgain = Math.min(nAgain, opts.extra.nAgain);
  }

  // The cap is the ceiling the die target clamps to (default 10); every point of
  // difficulty above it becomes a required success instead. Because reductions
  // subtract from the RAW difficulty, they strip that surcharge first and only
  // then lower the die target - the book's ordering, by arithmetic.
  const cap = Math.max(2, Math.min(10, spec.difficultyCap ?? 10));
  // The floor binds AFTER every reduction: a spell talked down to 1 still rolls
  // at the chronicle's minimum. 2 is the engine's own hard floor (a d10 target
  // of 1 would make every die a success).
  const floor = Math.max(2, Math.min(cap, spec.minDifficulty ?? 2));
  const rawDifficulty = difficulty;
  const dieDifficulty = Math.max(floor, Math.min(cap, rawDifficulty));
  const overflow = Math.max(0, rawDifficulty - cap);
  const policy = opts.overDifficulty ?? "extra-success";
  const impossible = overflow > 0 && policy === "impossible";

  let requires = Math.max(1, spec.requires);
  const notes: string[] = [];
  if (overflow > 0) {
    if (impossible) notes.push(`difficulty ${rawDifficulty} exceeds ${cap} -> impossible`);
    else { requires += overflow; notes.push(`difficulty ${rawDifficulty} > ${cap} -> +${overflow} required success${overflow === 1 ? "" : "es"}`); }
  }
  if (floor > 2 && rawDifficulty < floor) notes.push(`difficulty ${rawDifficulty} raised to the minimum ${floor}`);
  if (unknownTags.length) notes.push(`unknown tag${unknownTags.length === 1 ? "" : "s"}: ${unknownTags.join(", ")}`);

  return {
    spec, breakdown, dice: Math.max(0, dice), dieDifficulty, requires,
    automaticSuccesses, uncancelableSuccesses, nAgain, rawDifficulty, overflow, impossible, appliedTags, unknownTags, notes,
  };
}

type RollOutcomeKind = "success" | "failure" | "botch" | "impossible";
interface RollExecution {
  resolved: ResolvedRoll;
  result: RollResult | null;   // null when impossible (never rolled)
  met: boolean;                // requirement met
  outcome: RollOutcomeKind;
}

function executeRoll(
  spec: RollSpec, resolve: TraitResolver,
  opts: { rng?: Rng; overDifficulty?: OverDifficultyPolicy; extra?: Partial<RollModifier>; usedTags?: string[] } = {}
): RollExecution {
  const resolved = resolveSpec(spec, resolve, opts);
  if (resolved.impossible) return { resolved, result: null, met: false, outcome: "impossible" };
  const result = Dice.roll(resolved.dice, {
    difficulty: resolved.dieDifficulty,
    nAgain: resolved.nAgain,
    automaticSuccesses: resolved.automaticSuccesses,
    uncancelableSuccesses: resolved.uncancelableSuccesses,
    rng: opts.rng,
    label: prettyPool(spec.pool) || "Pool",
  });
  const met = !result.isBotch && result.net >= resolved.requires;
  const outcome: RollOutcomeKind = result.isBotch ? "botch" : (met ? "success" : "failure");
  return { resolved, result, met, outcome };
}

// A single-line summary (no character name; the caller prefixes that).
function formatExecution(exec: RollExecution): string {
  if (exec.outcome === "impossible") {
    return `${prettyPool(exec.resolved.spec.pool)}: impossible - difficulty ${exec.resolved.rawDifficulty} exceeds 10.`;
  }
  const r = exec.result!;
  const verdict = r.isBotch ? "botch"
    : (exec.met ? `meets requirement (${exec.resolved.requires})` : `short of requirement (${exec.resolved.requires})`);
  const extra = exec.resolved.notes.length ? ` [${exec.resolved.notes.join("; ")}]` : "";
  return `${r.message} - ${verdict}${extra}`;
}

// --- PARTIAL OVERRIDE (named rolls, and later extended-roll continuations) ---
// Return a copy of `base` with only the DEFINED fields of `overrides` applied.
// `pool` is intentionally never overridden - a saved roll keeps its own pool;
// callers tweak the knobs (difficulty, dice, requirement, tags). This is the
// shared primitive behind named rolls and the future extended-roll continuations
// (helpers changing the dice modifier, etc.).
function overrideSpec(base: RollSpec, overrides: Partial<RollSpec>): RollSpec {
  const merged: RollSpec = { ...base, tags: [...base.tags] };
  // A numeric difficulty override replaces any expression, and vice versa
  // (extractRollArgs supplies exactly one of them).
  if (overrides.difficulty !== undefined) { merged.difficulty = overrides.difficulty; merged.difficultyExpr = undefined; }
  if (overrides.difficultyExpr !== undefined) merged.difficultyExpr = overrides.difficultyExpr || undefined;
  if (overrides.difficultyMod !== undefined) merged.difficultyMod = overrides.difficultyMod;
  if (overrides.requires !== undefined) merged.requires = Math.max(1, overrides.requires);
  if (overrides.diceMod !== undefined) merged.diceMod = overrides.diceMod;
  if (overrides.tags !== undefined) merged.tags = overrides.tags.map(t => StringUtil.normalize(t)).filter(t => t.length > 0);
  if (overrides.difficultyCap !== undefined) merged.difficultyCap = overrides.difficultyCap;
  return merged;
}

// A short one-line summary of a spec, for save/list confirmations.
function describeSpec(spec: RollSpec): string {
  const mod = spec.difficultyMod ? (spec.difficultyMod > 0 ? `+${spec.difficultyMod}` : `${spec.difficultyMod}`) : "";
  const parts = [spec.pool, `diff ${spec.difficultyExpr ?? spec.difficulty}${mod}`];
  if (spec.requires !== 1) parts.push(`requires ${spec.requires}`);
  if (spec.diceMod) parts.push(`dice ${spec.diceMod > 0 ? "+" : ""}${spec.diceMod}`);
  if (spec.autoSuccesses) parts.push(`+${spec.autoSuccesses} auto`);
  if (spec.uncancelableSuccesses) parts.push(`+${spec.uncancelableSuccesses} sure`);
  if (spec.tags.length) parts.push(`tags ${spec.tags.join(",")}`);
  if (spec.difficultyCap !== undefined && spec.difficultyCap !== 10) parts.push(`cap ${spec.difficultyCap}`);
  return parts.join(", ");
}

// --- EXTENDED ROLLS (persistent, interval-aware accumulating actions) --------
// An extended action accumulates net successes toward `target` across up to
// `maxRolls` intervals (which may be far apart in time). A botch triggers the
// configurable `onBotch` policy. This state machine is pure; persistence and the
// commands live in game.ts.
type BotchPolicy = "fail" | "lose-successes" | "ignore";
type ExtendedStatus = "open" | "succeeded" | "failed";

interface ExtendedInterval {
  by: string;              // character who rolled this interval
  net: number;             // successes credited (0 on a botch)
  outcome: RollOutcomeKind;
  total: number;           // accumulated successes after this interval
}

interface ExtendedRoll {
  id: string;
  label: string;           // description ("" if none)
  base: RollSpec;          // the roll each interval makes
  target: number;          // successes needed to succeed
  maxRolls: number;        // intervals allowed
  interval: string;        // advisory spacing label ("" if none)
  onBotch: BotchPolicy;
  table?: string;          // success-table key read against each interval's net
  accumulated: number;
  rollsUsed: number;
  status: ExtendedStatus;
  log: ExtendedInterval[];
}

function parseBotchPolicy(s: string | undefined): BotchPolicy {
  const n = (s ?? "").trim().toLowerCase();
  if (n === "lose-successes" || n === "lose" || n === "reset") return "lose-successes";
  if (n === "ignore" || n === "continue") return "ignore";
  return "fail";
}

// Apply one interval's result to an OPEN action. Pure: returns a NEW action plus
// a short human note. Caller must ensure `action.status === "open"`.
function applyInterval(action: ExtendedRoll, exec: RollExecution, by: string): { action: ExtendedRoll; note: string } {
  const next: ExtendedRoll = { ...action, log: [...action.log] };
  const net = exec.result ? exec.result.net : 0;
  let credited = 0;
  let note: string;

  next.rollsUsed += 1;
  if (exec.outcome === "botch") {
    if (action.onBotch === "fail") { next.status = "failed"; note = "botch - the action fails"; }
    else if (action.onBotch === "lose-successes") { next.accumulated = 0; note = "botch - accumulated successes lost"; }
    else { note = "botch - counted as no progress"; }
  } else {
    credited = Math.max(0, net);
    next.accumulated += credited;
    note = `+${credited} (total ${next.accumulated}/${action.target})`;
  }

  if (next.status === "open") {
    if (next.accumulated >= action.target) next.status = "succeeded";
    else if (next.rollsUsed >= action.maxRolls) next.status = "failed";
  }
  next.log.push({ by, net: credited, outcome: exec.outcome, total: next.accumulated });
  return { action: next, note };
}

// One-line status summary.
function describeExtended(a: ExtendedRoll): string {
  const head = a.label ? `"${a.label}" ` : "";
  const bits = [`${a.accumulated}/${a.target} successes`, `roll ${a.rollsUsed}/${a.maxRolls}`];
  if (a.interval) bits.push(`interval ${a.interval}`);
  bits.push(a.status);
  return `${head}[${describeSpec(a.base)}] - ${bits.join(", ")}`;
}

// =============================================================================
// SUCCESS TABLES - what a number of successes MEANS
// -----------------------------------------------------------------------------
// A roll never interprets its own successes; it hands the count to a table.
// Tables are pure data: qualitative ladders (discipline effects, the classic
// degrees of success), direct numeric functions (damage: 1 level per success),
// or both. `cap` makes extra successes useless; `overflow` gives each batch of
// extras a rule-specified bonus beyond the last row.
// =============================================================================
interface SuccessTableRow { at: number; label: string; value?: number }
interface SuccessTable {
  name: string;
  description?: string;
  rows?: SuccessTableRow[];      // sorted ascending; the highest `at` <= n applies
  valuePerSuccess?: number;      // direct numeric output: value = counted * this
  cap?: number;                  // successes beyond this are useless
  overflow?: { per: number; label?: string; value?: number }; // per batch beyond the last row
  botch?: string;                // what a botch means here
  failure?: string;              // what failure means here
}
interface SuccessReading {
  table: string;
  outcome: RollOutcomeKind;
  successes: number;             // counted (after cap)
  wasted: number;                // beyond the cap
  label: string;
  value?: number;                // numeric output when the table defines one
  extra?: string;                // overflow annotation
}

function readSuccessTable(table: SuccessTable, outcome: RollOutcomeKind, successes: number): SuccessReading {
  const base: SuccessReading = { table: table.name, outcome, successes: 0, wasted: 0, label: "" };
  if (outcome === "botch") return { ...base, label: table.botch ?? "Botch" };
  if (outcome !== "success" || successes <= 0) return { ...base, label: table.failure ?? "Failure" };

  const counted = table.cap !== undefined ? Math.min(successes, table.cap) : successes;
  const wasted = successes - counted;
  let label = `${counted} success${counted === 1 ? "" : "es"}`;
  let value: number | undefined;
  let extra: string | undefined;

  if (table.valuePerSuccess !== undefined) value = counted * table.valuePerSuccess;
  const rows = [...(table.rows ?? [])].sort((a, b) => a.at - b.at);
  if (rows.length > 0) {
    const hit = [...rows].reverse().find(r => r.at <= counted);
    if (!hit) return { ...base, successes: counted, wasted, label: table.failure ?? "Failure" };
    label = hit.label;
    if (hit.value !== undefined) value = (value ?? 0) + hit.value;
    const last = rows[rows.length - 1];
    if (table.overflow && counted > last.at) {
      const batches = Math.floor((counted - last.at) / Math.max(1, table.overflow.per));
      if (batches > 0) {
        if (table.overflow.value !== undefined) value = (value ?? 0) + batches * table.overflow.value;
        extra = `+${batches} x ${table.overflow.label ?? "overflow"}`;
      }
    }
  }
  return { table: table.name, outcome, successes: counted, wasted, label, value, extra };
}

function describeTableReading(r: SuccessReading): string {
  const bits = [r.label];
  if (r.value !== undefined) bits.push(`= ${r.value}`);
  if (r.extra) bits.push(r.extra);
  if (r.wasted > 0) bits.push(`(${r.wasted} wasted)`);
  return bits.join(" ");
}

// A whole table laid out (for [[tables <name>]]): its ladder and every dimension
// that shapes a reading, so a Storyteller can see exactly what it does.
function describeTable(t: SuccessTable): string {
  const dims: string[] = [];
  const rows = [...(t.rows ?? [])].sort((a, b) => a.at - b.at);
  if (rows.length > 0) {
    dims.push(rows.map(r => `${r.at}:${r.label}${r.value !== undefined ? `=${r.value}` : ""}`).join(", "));
  }
  if (t.valuePerSuccess !== undefined) dims.push(`${t.valuePerSuccess}/success`);
  if (t.cap !== undefined) dims.push(`cap ${t.cap}`);
  if (t.overflow) dims.push(`overflow ${t.overflow.value ?? "?"}/${t.overflow.per} (${t.overflow.label ?? "overflow"})`);
  if (t.botch) dims.push(`botch: ${t.botch}`);
  if (t.failure) dims.push(`failure: ${t.failure}`);
  const head = t.description ? `${t.name} - ${t.description}` : t.name;
  return dims.length ? `${head} [${dims.join("; ")}]` : head;
}

// The [[define-table]] rows mini-grammar: comma-separated `<at>:<label>[=<value>]`
// items (e.g. "1:Cowed, 3:Terrified, 5:Broken=2"). Input arrives VERBATIM when
// backtick-quoted (labels are display text), so items are trimmed here; the
// normalized form (lowercased, hyphenated labels) parses identically.
// Missing/empty input is a valid empty ladder; a bad item is an error citing
// the grammar (a misconfigured table is refused, never half-stored).
function parseTableRows(raw: string | undefined): SuccessTableRow[] | { error: string } {
  if (!raw || !raw.trim()) return [];
  const rows: SuccessTableRow[] = [];
  // Rows separate on ";" when the text has one, else ",". Labels are prose and
  // often contain commas ("age, family, and whether the subject resisted"), so
  // a semicolon is the way to say "that comma is punctuation".
  const items = raw.includes(";") ? raw.split(";") : raw.split(",");
  for (const item of items) {
    const m = item.trim().match(/^(\d+)\s*:\s*([^=]+?)\s*(?:=\s*(-?\d+))?$/);
    if (!m || !m[2].trim()) {
      return { error: `Can't read row "${item.trim()}" - rows are "<successes>:<label>[=<value>]", comma-separated (e.g. 1:Cowed, 3:Terrified=2).` };
    }
    const row: SuccessTableRow = { at: parseInt(m[1], 10), label: m[2].trim() };
    if (m[3] !== undefined) row.value = parseInt(m[3], 10);
    rows.push(row);
  }
  return rows;
}

// The classic ladders every chronicle starts with; the lorebook can overlay
// more (wod:config:success-tables). Damage and soak are the "direct function"
// generalization: same mechanism, numeric output.
const DEFAULT_SUCCESS_TABLES: SuccessTable[] = [
  {
    name: "degrees", description: "Classic degrees of success",
    botch: "Botch - catastrophic failure", failure: "Failure",
    rows: [
      { at: 1, label: "Marginal" }, { at: 2, label: "Moderate" }, { at: 3, label: "Complete" },
      { at: 4, label: "Exceptional" }, { at: 5, label: "Phenomenal" },
    ],
  },
  { name: "damage", description: "Each success is one level of damage", valuePerSuccess: 1, botch: "Botch - you may hit an ally or yourself", failure: "No damage" },
  { name: "soak", description: "Each success soaks one level", valuePerSuccess: 1, failure: "Nothing soaked" },
  { name: "climbing", description: "~10 ft climbed per success (Storyteller may vary the distance)", valuePerSuccess: 10, botch: "Botch - you may become stuck, panic, or fall", failure: "No progress this interval - reposition or find a new route" },
];

class SuccessTableRegistry {
  private static _tables: Map<string, SuccessTable> =
    new Map(DEFAULT_SUCCESS_TABLES.map(t => [StringUtil.normalize(t.name), { ...t, name: StringUtil.normalize(t.name) }]));

  static register(table: SuccessTable): void {
    const name = StringUtil.normalize(table.name);
    SuccessTableRegistry._tables.set(name, { ...table, name });
  }
  static get(name: string): SuccessTable | undefined { return SuccessTableRegistry._tables.get(StringUtil.normalize(name)); }
  static all(): SuccessTable[] { return [...SuccessTableRegistry._tables.values()]; }
  static reset(): void {
    SuccessTableRegistry._tables = new Map(DEFAULT_SUCCESS_TABLES.map(t => [StringUtil.normalize(t.name), { ...t, name: StringUtil.normalize(t.name) }]));
  }
}

// =============================================================================
// RESISTED & CONTESTED ROLLS - two rolls, one comparison
// -----------------------------------------------------------------------------
// oWoD classic defaults: RESISTED - only the actor's margin over the resister
// counts; a tie (or the resister winning) means the action simply fails.
// CONTESTED - symmetric: more successes wins, a tie is a draw. A botched side
// contributes 0 successes (flagged); both sides botching is a mutual disaster.
// =============================================================================
type ContestMode = "resisted" | "contested";

// =============================================================================
// N SIDES, NOT TWO - a contest is a field, and two is just the small case
// -----------------------------------------------------------------------------
// Everything here used to be `a` and `b`: `aNet`/`bNet`, `winner: "a"|"b"`. Two
// men wrestling is one shape a contest takes, and three thieves reaching for the
// same purse is another - the rules are identical and only the arithmetic was
// hard-coded. So the primitive is a FIELD of entrants and the two-sided call is
// the case where the field has two.
//
// CONTESTED: the highest net takes it; several at the top is a draw between
// them (and everyone else still has a rank, which is what a race needs).
// RESISTED: the FIRST entrant is the actor and the rest resist him - he must
// beat the BEST of them, because "resisted" means somebody stopped you and it
// only takes one. A botch counts as zero and is said out loud.
// =============================================================================
interface ContestEntrant { name: string; exec: RollExecution }
interface ContestStanding { name: string; net: number; botch: boolean; rank: number }
interface FieldOutcome {
  mode: ContestMode;
  standings: ContestStanding[];       // best first; equal nets share a rank
  winners: string[];                  // empty = nobody; several = a tie at the top
  margin: number;                     // the winner's lead over the next rank (0 if tied)
  note: string;
}

// The net a side actually scored: a botch is zero, never negative.
function netOf(exec: RollExecution): { net: number; botch: boolean } {
  const botch = exec.outcome === "botch";
  return { net: botch ? 0 : Math.max(0, exec.result?.net ?? 0), botch };
}

function compareField(mode: ContestMode, entrants: ContestEntrant[]): FieldOutcome {
  const scored = entrants.map(e => ({ name: e.name, ...netOf(e.exec) }));
  const label = (n: string): string => StringUtil.toTitleCase(n);

  if (mode === "resisted") {
    // The actor against the best of everyone stopping him.
    const [actor, ...resisters] = scored;
    const standings: ContestStanding[] = [{ ...actor, rank: 1 }, ...resisters.map(r => ({ ...r, rank: 2 }))];
    const base = { mode, standings, winners: [] as string[], margin: 0 };
    if (!actor) return { ...base, note: "nobody acted" };
    if (actor.botch) return { ...base, note: "the actor botches" };
    const best = resisters.reduce((m, r) => Math.max(m, r.net), 0);
    const margin = actor.net - best;
    if (margin > 0) {
      const botched = resisters.filter(r => r.botch).map(r => label(r.name));
      return { ...base, winners: [actor.name], margin,
        note: `prevails by ${margin}${resisters.length > 1 ? ` over ${resisters.length} resisting` : ""}`
          + `${botched.length ? ` (${botched.join(", ")} botched)` : ""}` };
    }
    return { ...base, note: `the action is resisted${resisters.length > 1 ? ` (best of ${resisters.length})` : ""}` };
  }

  // Contested: rank the field. Equal nets share a rank, so a three-way tie at
  // the top is three winners and the next man is fourth.
  const order = [...scored].sort((x, y) => y.net - x.net);
  const standings: ContestStanding[] = [];
  let rank = 0, seen = 0, lastNet = Number.NaN;
  for (const one of order) {
    seen += 1;
    if (one.net !== lastNet) { rank = seen; lastNet = one.net; }
    standings.push({ ...one, rank });
  }
  if (!standings.length) return { mode, standings, winners: [], margin: 0, note: "nobody rolled" };
  if (standings.every(s => s.botch)) {
    return { mode, standings, winners: [], margin: 0, note: "everyone botches - mutual disaster" };
  }
  const top = standings.filter(s => s.rank === 1);
  const runnerUp = standings.find(s => s.rank !== 1);
  const botched = standings.filter(s => s.botch).map(s => label(s.name));
  const botchNote = botched.length ? ` (${botched.join(", ")} botched)` : "";
  if (top.length > 1) {
    return { mode, standings, winners: top.map(t => t.name), margin: 0,
      note: `tie at ${top[0].net} between ${top.map(t => label(t.name)).join(" and ")}${botchNote}` };
  }
  const margin = top[0].net - (runnerUp?.net ?? 0);
  return { mode, standings, winners: [top[0].name], margin,
    note: `${label(top[0].name)} wins by ${margin}${standings.length > 2 ? ` over ${standings.length - 1} others` : ""}${botchNote}` };
}

// How a field's standings read in a reply: "Erik 4, Rok 2, Sigrid 0 (botch)".
function describeStandings(o: FieldOutcome): string {
  return o.standings
    .map(s => `${StringUtil.toTitleCase(s.name)} ${s.net}${s.botch ? " (botch)" : ""}`)
    .join(", ");
}

// --- THE TWO-SIDED CASE ------------------------------------------------------
// Kept because most contests ARE two-sided and every caller reads a/b. It is
// compareField with a field of two, so there is one adjudication and not two.
interface ContestOutcome {
  mode: ContestMode;
  aNet: number; bNet: number;       // successes counted for each side (botch -> 0)
  aBotch: boolean; bBotch: boolean;
  winner: "a" | "b" | "none";
  margin: number;                   // the winner's lead (0 when none)
  note: string;
  field: FieldOutcome;              // the general answer, for a caller that wants it
}

function compareRolls(mode: ContestMode, a: RollExecution, b: RollExecution): ContestOutcome {
  const field = compareField(mode, [{ name: "a", exec: a }, { name: "b", exec: b }]);
  const A = netOf(a), B = netOf(b);
  const base = { mode, aNet: A.net, bNet: B.net, aBotch: A.botch, bBotch: B.botch, field };
  // The two-sided wording is older than the field and several tests read it, so
  // the special cases keep their exact phrasing.
  if (A.botch && B.botch) return { ...base, winner: "none", margin: 0, note: "both sides botch - mutual disaster" };
  if (mode === "resisted") {
    if (A.botch) return { ...base, winner: "none", margin: 0, note: "the actor botches" };
    const margin = A.net - B.net;
    if (margin > 0) return { ...base, winner: "a", margin, note: `prevails by ${margin}${B.botch ? " (resister botched)" : ""}` };
    return { ...base, winner: "none", margin: 0, note: "the action is resisted" };
  }
  if (A.net > B.net) return { ...base, winner: "a", margin: A.net - B.net, note: `wins by ${A.net - B.net}${B.botch ? " (opponent botched)" : ""}` };
  if (B.net > A.net) return { ...base, winner: "b", margin: B.net - A.net, note: `loses by ${B.net - A.net}${A.botch ? " (own botch)" : ""}` };
  return { ...base, winner: "none", margin: 0, note: "tie" };
}

// =============================================================================
// EXTENDED CONTESTS - both sides accumulate; first to the goal wins
// =============================================================================
// `char` is an opaque game-layer key (a character name, or undefined for an
// ad-hoc side); rolls.ts never reads it - the interpreter uses it to re-resolve
// this side's pool each round.
interface ContestSide { name: string; base: RollSpec; accumulated: number; char?: string; }
// "open" while it runs, "draw" when nobody got there first or the rounds ran
// out, otherwise the NAME of the winner. A name rather than "a"/"b" because
// there may be five of them.
type ContestStatus = string;
const CONTEST_OPEN = "open";
const CONTEST_DRAW = "draw";

interface ExtendedContest {
  id: string;
  label: string;
  sides: ContestSide[];             // TWO OR MORE. Index 0 is the actor.
  target: number;
  maxRounds: number;
  interval: string;                 // advisory spacing, like extended rolls
  onBotch: BotchPolicy;             // per side: fail -> that side loses outright
  rounds: number;
  status: ContestStatus;
  log: { round: number; nets: Record<string, number>; note: string }[];
}

// A contest saved before contests could have more than two sides kept `a` and
// `b`. Read it as a field of two; after one round it is stored the new way.
function migrateContest(raw: ExtendedContest & { a?: ContestSide; b?: ContestSide }): ExtendedContest {
  if (raw.sides?.length) return raw;
  const sides = [raw.a, raw.b].filter((x): x is ContestSide => x !== undefined);
  const status = raw.status === "a" ? sides[0]?.name : raw.status === "b" ? sides[1]?.name : raw.status;
  return { ...raw, sides, status: status ?? CONTEST_OPEN, log: raw.log ?? [] };
}

// One round: every side has rolled; accumulate and settle. Pure. `execs` is
// parallel to `contest.sides`.
function applyContestRound(c: ExtendedContest, execs: RollExecution[]): { contest: ExtendedContest; note: string } {
  const next: ExtendedContest = { ...c, sides: c.sides.map(s => ({ ...s })), log: [...c.log] };
  next.rounds += 1;
  const label = (n: string): string => StringUtil.toTitleCase(n);
  const scored = c.sides.map((side, i) => {
    const exec = execs[i];
    const botch = exec?.outcome === "botch";
    return { side, botch, net: botch ? 0 : Math.max(0, exec?.result?.net ?? 0) };
  });
  const nets: Record<string, number> = {};
  for (const s of scored) nets[s.side.name] = s.net;
  const botchers = scored.filter(s => s.botch);
  let note: string;

  if (botchers.length) {
    if (c.onBotch === "fail") {
      // A botch puts you out. Whoever is left takes it - unless nobody is.
      const standing = scored.filter(s => !s.botch);
      if (standing.length === 0) { next.status = CONTEST_DRAW; note = "everyone botches - the contest collapses"; }
      else if (standing.length === 1) {
        next.status = standing[0].side.name;
        note = `${botchers.map(b => label(b.side.name)).join(", ")} botch${botchers.length === 1 ? "es" : ""} - ${label(standing[0].side.name)} wins outright`;
      } else {
        // More than one left: the botchers are out, the rest carry on. This is
        // the case two sides could never reach.
        next.sides = next.sides.filter(s => !botchers.some(b => b.side.name === s.name));
        note = `${botchers.map(b => label(b.side.name)).join(", ")} botch out - ${next.sides.length} still in`;
      }
      if (next.status !== CONTEST_OPEN) {
        next.log.push({ round: next.rounds, nets, note });
        return { contest: next, note };
      }
    } else if (c.onBotch === "lose-successes") {
      for (const b of botchers) {
        const side = next.sides.find(s => s.name === b.side.name);
        if (side) side.accumulated = 0;
      }
      note = "botch - progress lost";
    } else note = "botch - a wasted round";
  } else note = "";

  for (const s of scored) {
    const side = next.sides.find(x => x.name === s.side.name);
    if (side) side.accumulated += s.net;
  }
  // Whoever crossed the line this round; if several did, the highest total took
  // it, and a dead heat stays OPEN because nobody got there first.
  const done = next.sides.filter(s => s.accumulated >= c.target);
  if (done.length) {
    const best = Math.max(...done.map(s => s.accumulated));
    const leaders = done.filter(s => s.accumulated === best);
    if (leaders.length === 1) next.status = leaders[0].name;
  }
  if (next.status === CONTEST_OPEN && next.rounds >= c.maxRounds) next.status = CONTEST_DRAW;
  const progress = next.sides.map(s => `${label(s.name)} ${s.accumulated}/${c.target}`).join(" vs ");
  note = note ? `${note}; ${progress}` : progress;
  next.log.push({ round: next.rounds, nets, note });
  return { contest: next, note };
}

function describeContest(c: ExtendedContest): string {
  const head = c.label ? `"${c.label}" ` : "";
  const state = c.status === CONTEST_OPEN ? "open"
    : c.status === CONTEST_DRAW ? "draw"
      : `${StringUtil.toTitleCase(c.status)} WINS`;
  const bits = [
    c.sides.map(s => `${StringUtil.toTitleCase(s.name)} ${s.accumulated}/${c.target}`).join(" vs "),
    `round ${c.rounds}/${c.maxRounds}`,
  ];
  if (c.interval) bits.push(`interval ${c.interval}`);
  bits.push(state);
  return `${head}${bits.join(", ")}`;
}
//#endregion src/rolls.ts

//#region src/rules.ts
// =============================================================================
// RULES - the Dark Ages data: rulesets, soak tables, templates, disciplines,
// merits & flaws defaults, and the SRD lorebook seed. Data over logic.
// =============================================================================

// The nine oWoD Attributes, by group. Fixed across every template, so they live
// in code (unlike the chronicle-variable ability/background lists in the
// lorebook). A fresh potential character seeds all nine at 1 (the free dot).
const ATTRIBUTES = {
  physical: ["Strength", "Dexterity", "Stamina"],
  social: ["Charisma", "Manipulation", "Appearance"],
  mental: ["Perception", "Intelligence", "Wits"],
} as const;
const ALL_ATTRIBUTES: readonly string[] = [
  ...ATTRIBUTES.physical, ...ATTRIBUTES.social, ...ATTRIBUTES.mental,
];

// =============================================================================
// CATEGORIES - "pick a Knowledge", "all Talents", "one of them an Attribute"
// -----------------------------------------------------------------------------
// A trait has a KIND (attribute, ability, background...) and, for the two that
// are allocated by priority, a CATEGORY: an Attribute is Physical, Social or
// Mental; an Ability is a Talent, a Skill or a Knowledge. Both have always been
// data - ATTRIBUTES above, and the three lorebook lists - but only the creation
// report could read them, so nothing else could say "pick a Knowledge and take
// -1 difficulty on it" or "every Talent is at +1".
//
// The ability lists are the CHRONICLE's (srd:abilities), so they are looked up
// through a registry that the lorebook overlays; these are the shipped defaults
// and the fallback when nothing has been loaded.
// =============================================================================
const ATTRIBUTE_CATEGORIES = ["physical", "social", "mental"] as const;
const ABILITY_CATEGORIES = ["talent", "skill", "knowledge"] as const;
type AttributeCategory = typeof ATTRIBUTE_CATEGORIES[number];
type AbilityCategory = typeof ABILITY_CATEGORIES[number];
type TraitCategory = AttributeCategory | AbilityCategory;
const ALL_TRAIT_CATEGORIES: readonly TraitCategory[] = [...ATTRIBUTE_CATEGORIES, ...ABILITY_CATEGORIES];

// Written either way ("knowledge" / "knowledges"), because a player and a card
// both spell a category list in the plural and a single pick in the singular.
function singularCategory(raw: string): string {
  const k = StringUtil.normalize(raw);
  const singular = k.endsWith("s") ? k.slice(0, -1) : k;
  return (ALL_TRAIT_CATEGORIES as readonly string[]).includes(singular) ? singular : k;
}
function isTraitCategory(raw: string): boolean {
  return (ALL_TRAIT_CATEGORIES as readonly string[]).includes(singularCategory(raw));
}

// Which of the three an Attribute is. Attributes are a fixed nine, so this is a
// rule rather than a lookup.
function attributeCategoryOf(name: string): AttributeCategory | undefined {
  const key = StringUtil.normalize(name);
  for (const category of ATTRIBUTE_CATEGORIES) {
    if (ATTRIBUTES[category].some(a => StringUtil.normalize(a) === key)) return category;
  }
  return undefined;
}

const DEFAULT_TALENTS = ["Alertness", "Athletics", "Awareness", "Brawl", "Empathy", "Expression", "Intimidation", "Leadership", "Legerdemain", "Subterfuge"];
const DEFAULT_SKILLS = ["Animal Ken", "Archery", "Commerce", "Crafts", "Etiquette", "Melee", "Performance", "Ride", "Stealth", "Survival"];
const DEFAULT_KNOWLEDGES = ["Academics", "Enigmas", "Hearth Wisdom", "Investigation", "Law", "Medicine", "Occult", "Politics", "Seneschal", "Theology"];

// --- CONFIGURATION ---
class RulesetConfig {
  constructor(
    public readonly AttrFreebieCost: number,
    public readonly AbilityFreebieCost: number,
    public readonly AttrXPMultiplier: number,
    public readonly AbilityXPMultiplier: number,
    public readonly UsesDowntime: boolean,
    public readonly AttrDowntimeCost: number = 0,
    public readonly AbilityDowntimeCost: number = 0
  ) {
    Object.freeze(this);
  }

  // Example rulesets
  static readonly VAMPIRE = new RulesetConfig(5, 2, 4, 2, true, 5, 2);
  static readonly MAGE = new RulesetConfig(5, 2, 4, 2, false);
}

// Mortals soak bashing with Stamina only; lethal/aggravated bypass them.
const MORTAL_SOAK: SoakSpec = {
  bashing: { soakable: true, pool: ["stamina"] },
  lethal: { soakable: false, pool: [] },
  aggravated: { soakable: false, pool: [] },
  difficulty: 6,
};
// Vampires soak bashing & lethal with Stamina (+Fortitude); aggravated needs
// Fortitude alone (no Fortitude trait -> empty pool -> nothing soaked).
const VAMPIRE_SOAK: SoakSpec = {
  bashing: { soakable: true, pool: ["stamina", "fortitude"] },
  lethal: { soakable: true, pool: ["stamina", "fortitude"] },
  aggravated: { soakable: true, pool: ["fortitude"] },
  difficulty: 6,
};
// Ghouls and revenants, though alive, soak like the half-vampires they are -
// the vitae in their veins does the knitting. A COPY, not an alias: a chronicle
// that changes what a vampire soaks must not silently change ghouls too.
const GHOUL_SOAK: SoakSpec = { ...VAMPIRE_SOAK };
// Mages innately soak like mortals (their real defence is magic, not modelled).
const MAGE_SOAK: SoakSpec = { ...MORTAL_SOAK };
// Demons (manifested) soak all three with Stamina.
const DEMON_SOAK: SoakSpec = {
  bashing: { soakable: true, pool: ["stamina"] },
  lethal: { soakable: true, pool: ["stamina"] },
  aggravated: { soakable: true, pool: ["stamina"] },
  difficulty: 6,
};
// Werewolves regenerate: like a demon they soak every severity with Stamina,
// and shrug off most punishment outright. Silver and fire are the exception -
// the SilverVulnerability reaction marks those packets Unsoakable, so this
// generous spec never even gets consulted for them.
const WEREWOLF_SOAK: SoakSpec = { ...DEMON_SOAK };

interface BloodStats { max: number; perTurn: number; }
// Vampire blood pool by generation (standard table; clamped to 3rd-15th).
const BLOOD_BY_GENERATION: Record<number, BloodStats> = {
  3: { max: 100, perTurn: 20 },
  4: { max: 50, perTurn: 10 },
  5: { max: 40, perTurn: 8 },
  6: { max: 30, perTurn: 6 },
  7: { max: 20, perTurn: 5 },
  8: { max: 15, perTurn: 3 },
  9: { max: 14, perTurn: 2 },
  10: { max: 13, perTurn: 1 },
  11: { max: 12, perTurn: 1 },
  12: { max: 11, perTurn: 1 },
  13: { max: 10, perTurn: 1 },
  14: { max: 10, perTurn: 1 },
  15: { max: 10, perTurn: 1 },
};
function bloodForGeneration(generation: number): BloodStats {
  const g = Math.max(3, Math.min(15, Math.round(generation)));
  return { ...BLOOD_BY_GENERATION[g] };
}

// =============================================================================
// MORALITY - Roads / Humanity (optional; Mages have none)
// =============================================================================
interface RoadDefinition {
  name: string;                       // e.g. "Road of Humanity"
  virtues: [string, string, string];  // the three Virtues this Road uses
  ratingVirtues: [string, string];    // which two sum to the starting rating
}

const ROAD_OF_HUMANITY: RoadDefinition = {
  name: "Road of Humanity",
  virtues: ["conscience", "self-control", "courage"],
  ratingVirtues: ["conscience", "self-control"],
};
const ROAD_OF_KINGS: RoadDefinition = {
  name: "Road of Kings",
  virtues: ["conviction", "self-control", "courage"],
  ratingVirtues: ["conviction", "self-control"],
};
const ROAD_OF_THE_BEAST: RoadDefinition = {
  name: "Road of the Beast",
  virtues: ["conviction", "instinct", "courage"],
  ratingVirtues: ["conviction", "instinct"],
};

// The Roads a character may WALK, by the name `[[choose road …]]` records.
// Without this the two beside Humanity were data nothing could ever reach.
const ROADS: Record<string, RoadDefinition> = {
  "road-of-humanity": ROAD_OF_HUMANITY,
  "road-of-kings": ROAD_OF_KINGS,
  "road-of-the-beast": ROAD_OF_THE_BEAST,
};
function roadByName(name: string): RoadDefinition | undefined {
  const key = StringUtil.normalize(name);
  for (const [id, road] of Object.entries(ROADS)) {
    if (id === key || StringUtil.normalize(road.name) === key || `road-of-${key}` === id) return road;
  }
  return undefined;
}

// How a template's morality is configured: which trait it is, its polarity,
// and how its starting value is derived.
interface MoralityConfig {
  name: string;
  polarity: MoralityPolarity;
  road?: RoadDefinition;        // virtue-based moralities (Roads / Humanity)
  deriveFromVirtues?: boolean;  // start = sum of the Road's two rating Virtues
  start?: number;               // default start when not derived from Virtues
}

const HUMANITY_MORALITY: MoralityConfig = {
  name: "Road of Humanity",
  polarity: "descending",
  road: ROAD_OF_HUMANITY,
  deriveFromVirtues: true,
};

// =============================================================================
// TEMPLATES - per-splat configuration including starting values
// =============================================================================
// THE CREATION BUDGET - what a fresh character is allowed to be
// -----------------------------------------------------------------------------
// Every Dark Ages template buys the same three priority ladders (Attributes
// 7/5/3 over a free dot each, Abilities 13/9/5 from nothing, five Background
// dots) and then its own splat pools on top: a vampire's four clan Discipline
// dots and seven Virtue dots, a mage's starting Quintessence. Freebies are the
// last purse, priced by the table in DEFAULT_ADVANCEMENT_COSTS.
//
// Nothing here ENFORCES: [[creation]] reports each pool against what the sheet
// actually holds, and the Storyteller decides. The point is that the numbers
// live in ONE place instead of in a book on someone's desk.
// =============================================================================
// Every one of these numbers may instead be an EXPRESSION over the character
// (core/expr.ts): a 7th-generation vampire's Attribute ceiling is
// `trait-max(generation)`, not 5. See §"DERIVED VALUES" below.
interface PriorityPools { primary: Numeric; secondary: Numeric; tertiary: Numeric }
// A trait whose start or ceiling differs from everyone else's - a Nosferatu has
// no Appearance at all, and never will.
interface TraitLimit { start?: Numeric; max?: Numeric; note?: string }

interface CreationBudget {
  attributes: PriorityPools;          // over one free dot in each
  attributeStart: Numeric;            // the free dot (1)
  attributeMax: Numeric;              // the usual ceiling (5)
  abilities: PriorityPools;
  abilityStart: Numeric;              // nothing free (0)
  abilityMax: Numeric;
  backgrounds: Numeric;
  freebies: Numeric;
  disciplines?: Numeric;              // vampires: four dots of CLAN Disciplines
  disciplineMax?: Numeric;            // and their ceiling, which generation raises
  virtues?: Numeric;                  // vampires: seven, over a free dot each
  virtueStart?: Numeric;              // the free dot in each Virtue (1)
  // Free dots the TEMPLATE hands out - a ghoul's Potence, a revenant's blood.
  grants?: CreationGrant[];
  // Most points of Flaws a character may take FOR freebies. Past it the Flaws
  // are still real, they just stop paying - unless a Storyteller says otherwise
  // ([[grant]] with a purse bonus, which is what his ruling actually is).
  flawMax?: Numeric;
  // Per-trait exceptions, by trait name.
  limits?: Record<string, TraitLimit>;
  notes?: string[];                   // the derived values a splat records
}

// What every Dark Ages character gets, whatever they are.
const BASE_CREATION: CreationBudget = {
  attributes: { primary: 7, secondary: 5, tertiary: 3 }, attributeStart: 1, attributeMax: 5,
  abilities: { primary: 13, secondary: 9, tertiary: 5 }, abilityStart: 0, abilityMax: 5,
  backgrounds: 5,
  freebies: 15,
  flawMax: 7,   // the usual ceiling on Flaws-for-freebies
};

// =============================================================================
// WHERE IT CAME FROM - a price of zero is not one fact but several
// -----------------------------------------------------------------------------
// `paid=0` said "this cost nothing" and stopped there, which conflates two
// different things (the owner's correction):
//
//   * A GHOUL'S FREE POTENCE DOT is not a favour - it is what a ghoul IS. The
//     template grants it, every ghoul has it, and a legality proof should say
//     "template" rather than shrug.
//   * A STORYTELLER'S BONUS is a ruling about THIS chronicle: "everyone here is
//     Suspect, so take the Flaw past your cap and keep the freebies it pays".
//     That is discretion, and it should be recorded as discretion.
//
// So a purchase records BOTH what it cost and where it came from. The source is
// what a legality proof reads: only `freebie` and `arcana` are creation purses,
// and anything from another source is legitimately outside them.
// =============================================================================
const GRANT_SOURCES: Record<string, string> = {
  freebies: "bought at creation, from the freebie purse",
  arcana: "bought at creation, from the arcana purse",
  template: "what this kind of creature simply is (a ghoul's free Potence dot)",
  clan: "the clan or bloodline it was born to",
  background: "conferred by a Background (a Talisman's library)",
  storyteller: "the Storyteller's discretion, for this chronicle",
  experience: "bought in play, with experience - not from a creation purse",
  maturation: "bought in downtime (🚧 no engine yet - recorded, never spent)",
};
// Which sources actually DRAW on a creation purse. Everything else is real, and
// costs the purse nothing, and says so.
const CREATION_SOURCES = ["freebies", "arcana"];
function sourceDrawsOnPurse(source: string | undefined): boolean {
  return source === undefined || CREATION_SOURCES.includes(StringUtil.normalize(source));
}
function grantSourceNote(source: string): string | undefined {
  return GRANT_SOURCES[StringUtil.normalize(source)];
}

// A dot the TEMPLATE hands out, free, to everyone of its kind. `choose` is the
// ghoul's case exactly: one dot of Potence, "which sometimes can be Fortitude".
interface CreationGrant {
  trait?: string;             // the specific trait, when there is no choice
  choose?: string[];          // ...or one of these, the player's pick
  rating: number;
  bucket?: string;            // which bucket it lands in (default: discipline)
  note?: string;
}
function describeCreationGrant(g: CreationGrant): string {
  const what = g.trait ? StringUtil.toTitleCase(g.trait)
    : (g.choose ?? []).map(c => StringUtil.toTitleCase(c)).join(" or ");
  return `${g.rating} free dot${g.rating === 1 ? "" : "s"} of ${what}${g.note ? ` (${g.note})` : ""}`;
}

function creationBudget(over: Partial<CreationBudget> = {}): CreationBudget {
  return { ...BASE_CREATION, ...over };
}

// =============================================================================
// PURSES - what a budget IS: an allowance, and what a dot costs to buy
// -----------------------------------------------------------------------------
// A purse used to be one string ("25" arcana points). That says how much you
// GET and nothing about what a thing COSTS, so the two prices a Dark Ages
// character actually pays live here beside the allowance: `freebie` (at
// creation) and `experience` (in play). Both are TEXT, exactly like
// DEFAULT_ADVANCEMENT_COSTS - "current x 5" is a price a Storyteller applies,
// and there is no advancement engine to evaluate it.
//
// NOT_PURCHASABLE is the one the engine DOES read: a purse you cannot shop
// from at all. The Ouroboros' Arcana are what he IS, not something he buys
// with freebies or earns with experience, and that is a rule rather than a
// missing number.
//
// 🚧 MATURATION - the third Dark Ages purse, spent in downtime - is deliberately
// NOT here yet. DEFAULT_ADVANCEMENT_COSTS still carries its column for the
// Storyteller; a purse grows a `maturation` price when the downtime engine
// exists to spend it (docs/memory.md roadmap).
// =============================================================================
const NOT_PURCHASABLE = "-";
interface BudgetDef {
  allows?: string;      // EXPRESSION over the character: "25", "role:willpower"
  freebie?: string;     // what ONE dot costs in freebies, or NOT_PURCHASABLE
  experience?: string;  // ... and what it costs in experience
  note?: string;
}
// A purse written the short way is just its allowance, which is what every
// template said before prices existed.
type BudgetEntry = string | BudgetDef;
function budgetDef(entry: BudgetEntry | undefined): BudgetDef {
  if (entry === undefined) return {};
  return typeof entry === "string" ? { allows: entry } : { ...entry };
}
// Is this price a price at all? Absent means nobody said (the Storyteller's
// call, as ever); NOT_PURCHASABLE means the answer is no.
function budgetBuyable(price: string | undefined): boolean {
  const p = (price ?? "").trim();
  return p !== "" && p !== NOT_PURCHASABLE;
}

// =============================================================================
// CAPABILITIES - what a creature can actually USE
// -----------------------------------------------------------------------------
// Holding a pool is not the same as being able to spend it. A mage has ten
// points of blood in his body and no way to use one as a vampire does. A
// vampire cannot harvest Quintessence from a cray, cannot gain it from Tass,
// and cannot burn a talisman's store on Awakened magic - he never Awakened at
// all. This matters most for a pool somebody is GIVEN: an object that grants
// Resolve is inert in the hands of a man who cannot channel it, and there are
// few demons and fewer thralls in these centuries.
//
// So a resource names the capabilities it NEEDS (ResourceDef.requires) and a
// template names the ones it HAS (TemplateConfig.Capabilities); a character may
// be attuned to one on top of that (PlayableCharacter.capabilities). `awakened`
// used to be a boolean of its own - it is simply the first of these.
// =============================================================================
const CAPABILITIES: Record<string, string> = {
  awakened: "works Awakened magic: may hold, harvest and spend Quintessence",
  vitae: "uses vampiric vitae as the Damned do - heal with it, boost with it",
  resolve: "channels the Resolve of the infernal - rare, in these centuries",
  // Not a pool but a CATEGORY: what opens the Arcana list at all. See
  // ARCANA_CAPABILITY below for why the gate lives here.
  arcana: "bound to the infernal: may hold Arcana and Taints (Devil's Due)",
};
function capabilityNote(name: string): string | undefined {
  return CAPABILITIES[StringUtil.normalize(name)];
}

// =============================================================================
// WHO HAS AN ARCANA LIST AT ALL
// -----------------------------------------------------------------------------
// Merits and Flaws are open to EVERY character to some degree. Arcana are not,
// and neither are Disciplines or Pillars: each of those belongs to a kind of
// creature, and to no other. A regular vampire's list of Merits and Flaws must
// contain no Arcana whatsoever - not "Arcana filed at the bottom", none.
//
// The gate is a capability rather than a template list, because the owner's
// ruling is that ANY splat may acquire it: "anyone can be a thrall of a demon,
// like a mage, a vampire, anyone can be". So a template that opens the list
// says so (thrall, demon), a sheet may be granted it on top ([[attune arcana]],
// for the campaign that says otherwise), and nothing else has to be edited.
const ARCANA_CAPABILITY = "arcana";
// Do these capabilities open the Arcana list? Pass what the character can use
// (template capabilities + attunements): CharacterResources.capabilities().
function capabilitiesOpenArcana(capabilities: string[]): boolean {
  return capabilities.map(c => StringUtil.normalize(c)).includes(ARCANA_CAPABILITY);
}

// =============================================================================
// DERIVED VALUES - the parts of a sheet that are consequences of other parts
// -----------------------------------------------------------------------------
// A vampire's Road is the sum of its two Road Virtues; its Willpower equals its
// Courage; its generation is 12 minus the Generation Background, and THAT sets
// how high its Attributes, Abilities and Disciplines may go. None of this is a
// number the player types - it is a number the sheet already implies - so it
// lives here as an EXPRESSION and is computed on demand, never written down.
//
// `when` is the whole distinction:
//   "start"  - a seed. The derivation answers while the sheet's own entry is
//              absent or 0; the moment the player rates it, the sheet wins.
//              (Willpower starts AT Courage, then freebies buy it up.)
//   "always" - an identity. It recomputes whatever the sheet says, because it
//              is not a rating at all. (Generation IS 12 minus the Background.)
// =============================================================================
interface Derivation {
  trait: string;                      // the name it answers to
  expr: string;                       // over the character (core/expr.ts)
  when?: "start" | "always";          // default "start"
  note?: string;                      // why, for the reports
}

// A vampire's trait ceiling by generation: the potent blood of an elder can
// hold more than five dots. 8th and thinner are the ordinary five.
const TRAIT_MAX_BY_GENERATION: Record<number, number> = {
  3: 10, 4: 9, 5: 8, 6: 7, 7: 6,
};
function traitMaxForGeneration(generation: number): number {
  return TRAIT_MAX_BY_GENERATION[Math.round(generation)] ?? 5;
}

// The Virtues a Road's rating sums, spelled the way an expression would -
// "conscience + self-control" for the Road of Humanity. What `road-virtues()`
// computes, and what a report prints to say WHICH two.
function roadRatingExpr(road: RoadDefinition): string {
  return road.ratingVirtues.map(v => StringUtil.normalize(v)).join(" + ");
}

// =============================================================================
type PoolKind = "tracker" | "pool";
// What spending `cost` points of a resource grants to a roll. Maps onto the
// RollModifier fields in rolls.ts (difficulty/dice/auto-successes), so a resource
// effect and a tag modifier flow through the same pipeline.
// --- THE EFFECT GRAMMAR ---
// One declarative sentence: spend [cost] -> apply [op] to [target] at [amount]
// per unit, lasting [duration], at most [limits]. `op` and `target` are OPEN
// vocabularies: a word the engine doesn't know yet ("arcana", "seduction",
// "majesty") is stored, shown, and adjudicated by the Storyteller until its
// interpreter lands - nothing is hardcoded to today's mechanics.
//
// Ops with interpreters today: "difficulty" | "dice" | "successes" | "nagain" |
// "uncancelable" (roll modifiers; an optional `target` names an action tag the
// roll must carry; "uncancelable" grants successes rolled 1s can never cancel),
// "increase" (raise a trait via the boost layer; `target` is a constraint - an
// attribute group, a record bucket, or a specific trait), "heal" (`target` =
// comma-separated severities or "all").
interface EffectOp {
  op: string;
  target?: string;
  amount?: number;          // magnitude per effect unit (default 1)
  fillToCap?: boolean;      // one application raises/heals to the cap
  cap?: number | string;    // literal, or a pool expression ("stamina+3") on the character
  // Gate: the op applies only when the roll's POOL actually used this trait
  // (the twin of the actionTag gate roll ops carry in `target`). A trait that
  // appears only in the difficulty expression does NOT count.
  trait?: string;
  // The op fires ONCE per spend, however many points ride it - "spending Living
  // Resolve for anything grants ONE un-cancelable success" without a 3-point
  // spend granting three.
  once?: boolean;
  // Gate: the op applies only while the character still HOLDS this much of a
  // resource (by name or role) - "while he has at least one Living Resolve, he
  // is immune to fear". Checked live, so it lapses the moment the pool empties.
  requiresResource?: { resource: string; atLeast: number };
}
interface EffectCost {
  units?: number;           // resource units per application (default 1)
  buys?: number;            // effect units per application (default 1)
  // A roll that reduces the units paid (possibly to zero) - e.g. Iron Will.
  reducedBy?: { pool: string; difficulty?: number; perSuccess?: number };
}
interface EffectDuration {
  kind: "instant" | "real" | "st" | "until";
  n?: number;               // count of `unit` ("real": minutes/hours; "st": turns/scenes)
  unit?: string;
  until?: string;           // kind "until": free-form affliction
}
interface EffectLimits {
  maxPerUse?: number;                  // applications per command (enforced)
  uses?: { n: number; per: string };   // tracked in the ledger; ST-enforced for now
  cooldown?: { n: number; unit: string }; // stored; ST-enforced for now
}
interface EffectSpec {
  label: string;
  apply: EffectOp[];        // [] = a pure cost (static spell fuel)
  cost?: EffectCost;
  duration?: EffectDuration;
  limits?: EffectLimits;
  targetMustBe?: string[];  // for effects on others; stored until targeting lands
}

// A scheduled way a resource refills itself as story time passes. [[advance-time]]
// counts the day boundaries and full moons it crossed and credits every rule
// whose gate (if any) is open. `requires` names active afflictions (def name
// or tag) that must be on the character - a single string, or an ARRAY that
// must ALL be active at once (full-rested AND in-sanctum, simultaneously).
interface RecoveryRule {
  amount: number;
  per: "day" | "full-moon";
  requires?: string | string[];
  // A Background/trait threshold the character must ALSO meet - the sanctum's
  // sleep point is Sanctum 4's benefit, not every sanctum's.
  requiresTrait?: { trait: string; atLeast: number };
  note?: string;            // shown beside the credit ("Umbral communion")
}

// A resource is a tracker/pool PLUS abstract `roles` it can fill and an optional
// spend `effect`. Roles are how templates compose/share resources: Quintessence
// carrying the "resolve" role IS "use Quintessence as Resolve" - pure data.
interface ResourceDef {
  name: string;
  kind: PoolKind;
  // start / max / perTurnLimit are NUMERIC: a number, or an expression over the
  // character (core/expr.ts). A mage's Quintessence capacity is not 20 - it is
  // "10 + 2 * background:fount", the Fount ladder said once. A fused pool is
  // "resource:quintessence:max + resource:blood:max", which is what Living
  // Resolve actually IS.
  start: Numeric;           // default starting value
  startMin?: number;        // inclusive lower bound for a chosen start
  startMax?: number;        // inclusive upper bound for a chosen start
  startOptions?: number[];  // discrete allowed starts (overrides min/max if set)
  max: Numeric;             // permanent cap (tracker) / capacity (pool)
  perTurnLimit?: Numeric;   // pools only (e.g. blood expenditure per turn)
  fromGeneration?: boolean; // blood pool: max & perTurn derived from Generation
  roles?: string[];         // abstract capabilities this resource fills
  // What a character must be CAPABLE OF to use this pool at all (CAPABILITIES).
  // Not the same as having it: a talisman may hand a mortal ten points of
  // Quintessence, and he will hold every one of them uselessly. Empty means
  // anyone can spend it.
  requires?: string[];
  // "Specifically replace any other resource": this resource takes over the
  // named ones - they are hidden from the character and their names resolve
  // here. Resource-level identity, not a spend effect.
  replaces?: string[];
  effect?: EffectSpec;      // the default (unnamed) spend effect
  effects?: Record<string, EffectSpec>; // named context effects (cast, heal, fuel, …)
  description?: string;     // free-text rules note, shown by [[resources]]
  recovery?: RecoveryRule[]; // clock-driven refills (see RecoveryRule)
  // When a roll's POOL names this resource (or one it replaces), the trait
  // resolves to min(cap, current) - a Willpower roll rolls CURRENT Willpower -
  // and each point above `negatesPenaltiesAbove` shields 1 die of pool
  // reductions (wound penalties, negative dice mods) on that roll.
  rollAs?: { cap?: number; negatesPenaltiesAbove?: number };
}
// A resource's spend effect: a named context effect if `name` is given, else the
// default. Named effects let one resource behave differently by situation (a
// Mage's Resolve "cast" bundle vs. its plain difficulty drop).
function resourceEffect(def: ResourceDef, name?: string): EffectSpec | undefined {
  return name ? def.effects?.[StringUtil.normalize(name)] : def.effect;
}

// Compact one-liner for [[resources]] listings and spend notes: the label plus
// any non-default cost/duration/limit dimensions.
function describeEffect(spec: EffectSpec): string {
  const bits: string[] = [spec.label];
  const c = spec.cost;
  if (c && ((c.units ?? 1) !== 1 || (c.buys ?? 1) !== 1 || c.reducedBy)) {
    bits.push(`cost ${c.units ?? 1} for ${c.buys ?? 1}${c.reducedBy ? `, roll ${c.reducedBy.pool} to reduce` : ""}`);
  }
  if (spec.duration && spec.duration.kind !== "instant") {
    const d = spec.duration;
    bits.push(`lasts ${d.kind === "until" ? `until ${d.until}` : `${d.n ?? 1} ${d.unit ?? d.kind}`}`);
  }
  if (spec.limits?.uses) bits.push(`${spec.limits.uses.n}/${spec.limits.uses.per}`);
  if (spec.limits?.cooldown) bits.push(`cooldown ${spec.limits.cooldown.n} ${spec.limits.cooldown.unit}`);
  return bits.join("; ");
}

// Reusable builders so shared roles/effects are configured once.
function willpowerResource(start: number): ResourceDef {
  return {
    name: "willpower", kind: "tracker", start, startMin: 1, startMax: 10, max: 10,
    roles: ["willpower"],
    // Spent Willpower buys CERTAINTY: successes rolled 1s can never cancel, one
    // per point - but a mind can only hold so much of it at once, so the total
    // is capped by Foundation (uncancelableCap; 1 for the unawakened).
    effect: { label: "Willpower: +1 un-cancelable success (one per action; a SPELL may stack them up to the Foundation)", apply: [{ op: "uncancelable", amount: 1 }] },
    // Willpower is also static spell fuel (Sorcerers, some Thaumaturgy): a
    // mandatory pure cost with no dice bonus - `spend=willpower:fuel!`.
    effects: { fuel: { label: "Willpower spent as static spell fuel", apply: [], cost: { units: 1 } } },
  };
}
function resolveResource(over: Partial<ResourceDef> = {}): ResourceDef {
  return {
    name: "resolve", kind: "tracker", start: 3, startMin: 1, startMax: 10, max: 10,
    roles: ["resolve", "magic-fuel"],
    // Resolve is the rarest substance in these centuries: a handful of demons
    // and their thralls. Anyone else holding it holds it and no more.
    requires: ["resolve"],
    effect: { label: "Resolve: -2 difficulty", apply: [{ op: "difficulty", amount: -2 }] },
    // The whole deal when a mage channels Resolve into a spell (limited per
    // scene as a usage-ledger demo; the Storyteller enforces the reset).
    effects: {
      cast: {
        label: "Resolve fuels the spell: +1 success, 8-again, -2 difficulty",
        apply: [{ op: "successes", amount: 1 }, { op: "nagain", amount: 8 }, { op: "difficulty", amount: -2 }],
        limits: { uses: { n: 3, per: "scene" } },
      },
    },
    ...over,
  };
}
function bloodResource(over: Partial<ResourceDef> = {}): ResourceDef {
  return {
    name: "blood", kind: "pool", start: 10, max: 10, perTurnLimit: 1,
    // `heal` is a ROLE, not just the name of an effect below: it says "this is
    // the substance this character mends himself with", so [[spend heal 2]]
    // finds it without knowing what it is called. Whether a resource CAN heal
    // is the `heal` effect; how much, and how often aggravated damage may be
    // mended, is 🚧 unmodelled - the effect says 1 box per point and the
    // Storyteller rules the rest.
    roles: ["blood", "heal"],
    // Every living thing has blood. Only the Damned and those they sustain can
    // DO anything with it - a mage's ten points are just a mage's ten points.
    requires: ["vitae"],
    effects: {
      heal: {
        label: "Blood knits the body: heal 1 bashing/lethal per point",
        apply: [{ op: "heal", target: "bashing,lethal", amount: 1 }],
      },
      boost: {
        label: "Blood surges a Physical Attribute: +1 per point",
        apply: [{ op: "increase", target: "physical", amount: 1 }],
        duration: { kind: "st", n: 1, unit: "scene" },
      },
    },
    ...over,
  };
}

class TemplateConfig {
  constructor(
    public readonly Name: string,
    public readonly Rules: RulesetConfig,
    public readonly Pools: ResourceDef[],
    public readonly Soak: SoakSpec,
    // The template's morality (a Road/Humanity, or an ascending Torment), or
    // null for splats without one (Mage, Werewolf).
    public readonly Morality: MoralityConfig | null,
    public readonly HasVirtues: boolean,
    public readonly HealthLevels: HealthLevelDef[] = STANDARD_HEALTH_LEVELS,
    // Innate damage reactions granted to every character of this template
    // (e.g. a vampire's undead physiology). Copied onto the character at build
    // time so per-character armour can be appended without touching the template.
    public readonly Reactions: DamageReaction[] = [],
    // What this creature can USE (see CAPABILITIES). `awakened` is one of these
    // - Sanctum, Library and Cray benefits are all predicated on it, and the
    // sleeping world gets nothing from a place of power.
    public readonly Capabilities: string[] = [],
    // What this template may SPEND, per purse: an allowance EXPRESSION ("15",
    // or one budget written in terms of another), and optionally what a dot
    // costs from the freebie and experience purses (see BudgetDef). A sheet may
    // override any of them (PlayableCharacter.budgets). A purse with no budget
    // anywhere is the Storyteller's call, and [[budget]] says so rather than
    // inventing a number.
    public readonly Budgets: Record<string, BudgetEntry> = {},
    // What a fresh character of this template may be (see CreationBudget).
    // Reported by [[creation]], enforced by nobody yet.
    public readonly Creation: CreationBudget = BASE_CREATION,
    // The values this splat's sheet IMPLIES rather than states (see Derivation).
    public readonly Derived: Derivation[] = [],
    // The Disciplines this template counts as its own, on top of (or instead
    // of) whatever the character's clan or bloodline family grants. See
    // DisciplineAffinity: this is how a creature with no clan at all still has
    // Disciplines that are properly his.
    public readonly Affinity: DisciplineAffinity = { disciplines: [] }
  ) {}

  // Resources is the modern name for Pools (trackers + pools with roles/effects).
  get Resources(): ResourceDef[] { return this.Pools; }

  // Awakened is a CAPABILITY now, not a field of its own - this is the name
  // every reader already knew it by.
  get Awakened(): boolean { return this.Capabilities.includes("awakened"); }

  // Can a character of this template actually use that pool? A resource with no
  // `requires` is usable by anyone; the answer names what is MISSING, because
  // "you cannot" is worth nothing without "because you never Awakened".
  CannotUse(def: ResourceDef): string[] {
    return (def.requires ?? []).map(r => StringUtil.normalize(r)).filter(r => !this.Capabilities.includes(r));
  }

  GetPool(name: string): ResourceDef | undefined {
    const n = StringUtil.normalize(name);
    return this.Pools.find(p => StringUtil.normalize(p.name) === n);
  }
}

