//#region src/ui-text.ts
// =============================================================================
// UI TEXT - every user-facing string the windows show
// -----------------------------------------------------------------------------
// window.ts holds LAYOUT and BEHAVIOUR; this holds the words. Change a label,
// a button, a placeholder or a refusal here and nowhere else - a test fails the
// build if a bare string literal creeps back into a window's part tree.
//
// What is deliberately NOT here: the labels and placeholders of a field that a
// CommandSpec already describes. Those come from the spec's `desc` (the label),
// `example` (the placeholder a form shows) and `hint` (the grammar [[help]]
// prints), so the window and the help text can never drift apart - that is the
// same one-source-of-truth rule the forms themselves are built on. These
// entries are only the strings no spec can own: window chrome, buttons, the
// windows' own framing of a shared field, and their refusals.
//
// Pure: no imports, no host access.
// =============================================================================

const UI_TEXT = {
  // Chrome every window shares.
  common: {
    create: "Create",
    close: "Close",
    cancel: "Cancel",
    clear: "(clear)",
    // The picker: a button beside a field, and the modal it opens.
    chooseButton: (key: string): string => `Choose ${key}…`,
    chooseTitle: (key: string): string => `Choose ${key}`,
    // A required field left blank, named by its own label.
    needs: (label: string): string => `Needs ${label}.`,
  },

  constraint: {
    title: "Define constraint group",
    blurb: "**Define a constraint group** (exclusive / restricted / forbidden)",
    opened: "Opened the constraint-group window. Fill it in and press Create (it runs [[define-constraint]]).",
  },

  table: {
    title: "Define success table",
    blurb: "**Define a success table** (ladder rows, numeric output, or both)",
    opened: "Opened the success-table window. Fill it in and press Create (it runs [[define-table]]).",
  },

  merit: {
    title: "Define merit / flaw",
    blurb: "**Define a Merit or Flaw.** `grants` names the affliction it turns on when taken - "
      + "pick one that exists, or type a new name and it will be defined too.",
    opened: "Opened the merit window. Fill it in and press Create (it runs [[define-merit]]).",
  },

  arcanum: {
    title: "Define arcanum / taint",
    blurb: "**Define an Arcanum or Taint** (Dark Ages: Devil's Due). Their own category, "
      + "their own purse - not merits. `per-template` gives the printed \"(7/5)\" price.",
    opened: "Opened the arcanum window. Fill it in and press Create (it runs [[define-arcanum]]).",
  },

  affliction: {
    title: "Define affliction",
    blurb: "**Define an affliction** (bindings, chains, mirrors, tags)",
    opened: "Opened the affliction window. Fill it in and press Create (it runs [[define-affliction]]).",
  },

  afflict: {
    title: "Afflict an affliction",
    blurb: "**Afflict an affliction** - pick one; its binding slots appear below.",
    afflictionLabel: "Affliction",
    afflictionPlaceholder: "e.g. feral-whispers",
    // `on` takes its label from [[afflict]]'s own spec; this is only the hint
    // inside the empty field.
    targetPlaceholder: "name or @alias",
    // One field per binding slot the chosen def declares - the def's vocabulary
    // is the Storyteller's, so the slot name is the label.
    bindingLabel: (slot: string): string => `Binding: ${slot}`,
    afflictButton: "Afflict",
    needsAffliction: "Pick an affliction first.",
    opened: "Opened the afflict window. Pick an affliction, fill its bindings, and press Afflict (it runs [[afflict]]).",
  },

  roll: {
    title: "Build a roll",
    blurb: "**Build a roll** - Roll fires it; Save stores it as a named roll.",
    // "For" and "Pool" are this window's framing of fields three verbs share
    // ([[roll]] / [[roll-for]] / [[name-roll]]), so they are its words, not a
    // spec's.
    forLabel: "For (blank = the current character)",
    forPlaceholder: "name",
    poolLabel: "Pool",
    poolPlaceholder: "e.g. dexterity+melee, or @saved",
    opposedLabel: "Opposed (Save bakes a contest; opponent supplied at play via vs=)",
    opposedNone: "none",
    vsPoolLabel: "vs-pool (opposition's pool; blank = your own pool)",
    vsPoolPlaceholder: "e.g. perception+alertness",
    vsDifficultyLabel: "vs-difficulty (opposition's difficulty; optional)",
    saveAsLabel: "Save as (optional - Save stores the roll under this name)",
    saveAsPlaceholder: "e.g. strike",
    rollButton: "Roll",
    saveButton: "Save",
    needsPool: "Needs a pool.",
    needsSaveName: "Needs a Save-as name to save.",
    opened: "Opened the roll window. Build the pool and knobs, then Roll (runs [[roll]] / [[roll-for]]) or Save (runs [[name-roll]]).",
  },
} as const;
//#endregion src/ui-text.ts

//#region src/window.ts
// =============================================================================
// WINDOWS - api.v1.ui forms that EMIT commands (no separate execution path)
// -----------------------------------------------------------------------------
// This module is LAYOUT and BEHAVIOUR only: every word it shows comes from
// somewhere else. A field the verb's CommandSpec describes takes its label from
// `desc` and its placeholder from `example`, so the form and [[help]] can never
// disagree; everything a spec cannot own (titles, buttons, refusals, a window's
// own framing of a shared field) lives in ui-text.ts. A test fails the build if
// a bare string literal reappears in a part tree here.
//
// A wizard-window is a UI over the command layer: it renders a form with UI
// Parts, binds each field to STORY storage via a `story:`-prefixed storageKey
// (see WHERE A FORM FIELD ACTUALLY LIVES below), and on submit composes a
// [[command]] string and routes it through the SAME CommandRouter every other
// command uses. The form itself is DERIVED from the verb's CommandSpec - the
// window duplicates no grammar: enum params render as button rows (from the
// spec's options, which reference the rules vocabularies), ints as number
// inputs, everything else as text inputs; composeCommand does the one
// sanitizing composition. Windows that need DOMAIN-driven fields (an affliction
// def's binding slots) will build their part tree by hand and still submit
// through composeCommand - the spec covers the static shape (next pass).
//
// A real NovelAI window can't render off-host, so the host mock records the
// part tree and lets tests fire button callbacks (see host.ts __ui* helpers) -
// which exercises the whole window -> command -> store path without a screen.
// =============================================================================

const WKEY = (verb: string, key: string): string => `win:${verb}:${key}`;

// --- WHERE A FORM FIELD ACTUALLY LIVES ---------------------------------------
// One place, because getting this wrong is INVISIBLE. The host syncs an input's
// value to the store its `storageKey` NAMES, and this is MEASURED on-host
// (scripts/probe-window-field.ts), not inferred:
//
//   storageKey "foo"          -> api.v1.storage["foo"]          (per SCRIPT)
//   storageKey "story:foo"    -> api.v1.storyStorage["foo"]     (per STORY)
//   storageKey "history:foo"  -> api.v1.historyStorage["foo"]   (undo-aware)
//
// This engine wrote UNPREFIXED keys - so the host filed them under
// `api.v1.storage` - and then read them back out of `tempStorage`. Two stores
// that never meet, so EVERY window field was permanently empty: [[win-roll]]'s
// Roll button read an empty pool and refused, and the other windows composed
// their command with every knob blank.
//
// `story:` is the right store rather than merely a working one, and the wrong
// one is actively harmful. `api.v1.storage` is where an UNPREFIXED key goes,
// and for an ACCOUNT script that store is account-level - shared across every
// story on the account. A form field left unprefixed would therefore leak one
// chronicle's answers into the next. A form belongs to the STORY being played,
// not to the script that drew it, and storyStorage is also what makes window
// state survive the multi-script split, where several units share one store and
// a window opened by one unit is readable by the unit that owns the verb.
//
// So: the engine NEVER writes api.v1.storage. A test asserts it stays empty.
const UI_FIELD_STORE = "story:";
const fieldKey = (key: string): string => `${UI_FIELD_STORE}${key}`;

// PRESENCE, not truthiness - a field the player deliberately cleared reads as
// cleared rather than as absent.
// Through the counter like everything else. These are the keys the HOST writes
// on our behalf when a field has a `storageKey`, so they are bare rather than
// prefixed - but a bare key is still somebody's key, and the rule is that no
// code outside StorageDesk names api.v1.*Storage.
async function readField(key: string): Promise<string> {
  const raw = await StorageDesk.request("get", STORE.story, key);
  return raw === undefined || raw === null ? "" : String(raw).trim();
}
async function writeField(key: string, value: string): Promise<void> {
  await StorageDesk.request("set", STORE.story, key, value);
}

// Every window ends the same two ways: a Close beside whatever buttons it owns,
// and the last reply shown beneath. One definition, so all three agree on what
// a dismissed window and a shown result look like.
const closeButton = (part: UiPartHelpers, handle: { close: () => void }): UIPart =>
  part.button({ text: UI_TEXT.common.close, callback: () => handle.close() });
const resultBox = (part: UiPartHelpers, result: string | undefined): UIPart[] =>
  result ? [part.box({ content: [part.text({ text: result })] })] : [];

// A field the spec describes labels itself: `desc` is the label, `example` the
// placeholder. Falling back to the bare key keeps a spec that says nothing
// from rendering an empty label.
const labelOf = (spec: CommandSpec | undefined, key: string): string => {
  const p = (spec?.params ?? []).find(x => x.key === key);
  return p?.desc ?? key;
};

// A row of buttons behaving as a single-select: the current value is marked
// with a bullet; clicking one writes it to STORY storage and re-renders.
// What a flag offers in a window. "" is the third answer - say nothing and let
// the verb's own default stand - and it composes to nothing.
const BOOL_OPTIONS = ["true", "false", ""];

function selectorRow(part: UiPartHelpers, verb: string, p: ParamSpec, current: string, rerender: () => Promise<void>): UIPart {
  const buttons = (p.options ?? []).map(o => part.button({
    text: `${o === current ? "• " : ""}${o === "" ? "(default)" : o}`,
    callback: async () => { await writeField(WKEY(verb, p.key), o); await rerender(); },
  }));
  return part.row({ content: [part.text({ text: `${p.desc ?? p.key}:` }), ...buttons] });
}

// --- THE PICKER (selection-widgets mode 2, docs/ui-parts.md) -----------------
// A dropdown substitute for lists too long to inline: a text input (typing
// stays live - mode 3) next to a "Choose <key>…" button that opens a MODAL
// with one button per option; the current value's button is marked ✅;
// picking writes the field through writeField, closes the modal, and
// re-renders the window. `options` is a thunk so dynamic lists (affliction
// registry, tables) are read at open time.
interface PickerOption { value: string; label?: string }

async function openPickerModal(key: string, storageKey: string, options: () => Promise<PickerOption[]>, rerender: () => Promise<void>): Promise<void> {
  const part = api.v1.ui.part;
  // `storageKey` is the RAW key here; pickerField adds the store prefix for the
  // input it renders, and the modal reads/writes the same field through the
  // same pair of helpers, so the two halves cannot drift apart again.
  const current = await readField(storageKey);
  const opts = await options();
  const handle = await api.v1.ui.modal.open({ title: UI_TEXT.common.chooseTitle(key), size: "small", content: [] });
  const pick = (value: string) => async (): Promise<void> => {
    await writeField(storageKey, value);
    await handle.close();
    await rerender();
  };
  await handle.update({ content: [part.column({ content: [
    ...opts.map(o => part.button({ text: `${o.value === current ? "✅ " : ""}${o.label ?? o.value}`, callback: pick(o.value) })),
    part.button({ text: UI_TEXT.common.clear, callback: pick("") }),
    part.button({ text: UI_TEXT.common.cancel, callback: () => handle.close() }),
  ] })] });
}

function pickerField(part: UiPartHelpers, opts: {
  key: string;                                  // short name: labels the Choose button
  label: string;                                // field label above the input
  storageKey: string;
  options: () => Promise<PickerOption[]>;
  rerender: () => Promise<void>;
  placeholder?: string;
}): UIPart {
  return part.column({ content: [
    part.text({ text: opts.label }),
    part.row({ content: [
      part.textInput({ storageKey: fieldKey(opts.storageKey), placeholder: opts.placeholder }),
      part.button({ text: UI_TEXT.common.chooseButton(opts.key), callback: () => openPickerModal(opts.key, opts.storageKey, opts.options, opts.rerender) }),
    ] }),
  ] });
}

// Read the form's story-storage fields, compose the command, route it, and show
// the OOC reply in-window.
async function submitCommand(verb: string, spec: CommandSpec, rerender: (result?: string) => Promise<void>): Promise<void> {
  const values: Record<string, string> = {};
  for (const p of spec.params ?? []) {
    values[p.key] = await readField(WKEY(verb, p.key));
  }
  const required = (spec.params ?? []).find(p => p.required && !values[p.key] && !p.default);
  if (required) { await rerender(UI_TEXT.common.needs(required.desc ?? required.key)); return; }
  const reply = await CommandRouter.route(composeCommand(verb, values, spec));
  await rerender(reply);
}

// Open a window whose form is the verb's CommandSpec. Returns whether a spec
// existed to render.
async function openCommandWindow(verb: string, opts?: {
  title?: string; blurb?: string; submitLabel?: string;
  // Per-param option pickers: a param key listed here renders a pickerField
  // (typing + Choose-modal) instead of a bare text input - same temp key, so
  // composeCommand is untouched.
  pickers?: Record<string, () => Promise<PickerOption[]>>;
}): Promise<boolean> {
  const spec = CommandRouter.specFor(verb);
  if (!spec) return false;
  const part = api.v1.ui.part;

  // Pre-seed enum defaults so the selector rows show a selection immediately.
  for (const p of spec.params ?? []) {
    if (p.default !== undefined && !(await readField(WKEY(verb, p.key)))) {
      await writeField(WKEY(verb, p.key), p.default);
    }
  }

  const handle = await api.v1.ui.window.open({ title: opts?.title ?? `[[${verb}]]`, content: [], defaultWidth: 480, defaultHeight: 600 });

  const render = async (result?: string): Promise<void> => {
    const content: UIPart[] = [];
    if (opts?.blurb) content.push(part.text({ text: opts.blurb, markdown: true }));
    for (const p of spec.params ?? []) {
      if (p.type === "bool") {
        // A flag has one vocabulary, so the spec does not restate it: the
        // window offers both answers and "unset" (leave it to the verb).
        const current = (await readField(WKEY(verb, p.key))) || p.default || "";
        content.push(selectorRow(part, verb, { ...p, options: BOOL_OPTIONS }, current, () => render()));
      } else if (p.type === "enum" && p.options?.length) {
        const current = (await readField(WKEY(verb, p.key))) || p.default || "";
        content.push(selectorRow(part, verb, p, current, () => render()));
      } else if (p.type === "int") {
        content.push(part.text({ text: p.desc ?? p.key }));
        content.push(part.numberInput({ storageKey: fieldKey(WKEY(verb, p.key)) }));
      } else if (opts?.pickers?.[p.key]) {
        content.push(pickerField(part, {
          key: p.key, label: p.desc ?? p.key, storageKey: WKEY(verb, p.key),
          options: opts.pickers[p.key], rerender: () => render(), placeholder: p.example,
        }));
      } else {
        content.push(part.text({ text: p.desc ?? p.key }));
        content.push(part.textInput({ storageKey: fieldKey(WKEY(verb, p.key)), placeholder: p.example }));
      }
    }
    content.push(part.row({ content: [
      part.button({ text: opts?.submitLabel ?? UI_TEXT.common.create, callback: () => submitCommand(verb, spec, render) }),
      closeButton(part, handle),
    ] }));
    content.push(...resultBox(part, result));
    await handle.update({ content });
  };

  await render();
  return true;
}

// The constraint-group window: [[define-constraint]]'s spec rendered as a form.
